"use client"

import React from "react"
import {
    cn,
} from "@heroui/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import {
    BackgroundEffect,
} from "@/modules/types/enums/background-effect"
import {
    EmberEffect,
} from "./effects/EmberEffect"
import {
    WaveEffect,
} from "./effects/WaveEffect"
import {
    SnowEffect,
} from "./effects/SnowEffect"
import {
    RainEffect,
} from "./effects/RainEffect"
import {
    BubblesEffect,
} from "./effects/BubblesEffect"
import {
    FirefliesEffect,
} from "./effects/FirefliesEffect"
import {
    StarsEffect,
} from "./effects/StarsEffect"
import {
    AuroraEffect,
} from "./effects/AuroraEffect"
import {
    CircuitEffect,
} from "./effects/CircuitEffect"

/** Props for {@link AmbientBackground}. */
export interface AmbientBackgroundProps extends WithClassNames<undefined> {
    /** Which ambient effect to render (user's Settings ΓåÆ "Appearance" choice). Defaults to `None`. */
    effect?: BackgroundEffect
}

/**
 * App-wide ambient background ΓÇö one of several decorative effects (Settings ΓåÆ
 * "Appearance") sitting `fixed inset-0` behind everything (negative z-index,
 * non-interactive) so it stays put while the page scrolls. Every effect tints
 * from the `--accent` token, so it tracks the user's chosen accent color
 * automatically; the caller hides this entirely on `/learn` (reading column
 * stays uncluttered) and honours `prefers-reduced-motion` per-effect in
 * `globals.css`.
 *
 * Pure presenter: owns all of its style, takes no store/data beyond the
 * `effect` prop. Each effect's particle layout is seeded deterministically
 * (see `useSeededParticles`) so server + client markup match ΓÇö no hydration
 * mismatch and no `Math.random` at render.
 *
 * @param props - optional className (placement) + which `effect` to render.
 * @see Story: .storybook/stories/blocks/layout/AmbientBackground/AmbientBackground.stories
 */
export const AmbientBackground = ({
    className,
    effect = BackgroundEffect.None,
}: AmbientBackgroundProps) => {
    if (effect === BackgroundEffect.None) {
        return null
    }

    return (
        <div
            aria-hidden="true"
            className={cn(
                "pointer-events-none fixed inset-0 -z-10 overflow-hidden",
                className,
            )}
        >
            {effect === BackgroundEffect.Ember ? <EmberEffect /> : null}
            {effect === BackgroundEffect.Wave ? <WaveEffect /> : null}
            {effect === BackgroundEffect.Snow ? <SnowEffect /> : null}
            {effect === BackgroundEffect.Rain ? <RainEffect /> : null}
            {effect === BackgroundEffect.Bubbles ? <BubblesEffect /> : null}
            {effect === BackgroundEffect.Fireflies ? <FirefliesEffect /> : null}
            {effect === BackgroundEffect.Stars ? <StarsEffect /> : null}
            {effect === BackgroundEffect.Aurora ? <AuroraEffect /> : null}
            {effect === BackgroundEffect.Circuit ? <CircuitEffect /> : null}
        </div>
    )
}

import React, {
    useEffect,
    useState,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    BrandLogo,
} from "@/components/blocks/identity/BrandLogo"

/** Minimum on-screen time so the splash reads as deliberate, not a flash. */
const MIN_VISIBLE_MS = 550
/** Opacity fade-out duration once the app is ready. */
const FADE_MS = 350

/** Props for {@link _AppSplash} ΓÇö presentational; the loading label already resolved. */
export interface AppSplashProps {
    /** Already-localized loading label (used both as the `aria-label` and the visible caption). */
    loadingLabel: string
}

/**
 * AppSplash ΓÇö the full-screen entry "suspense" screen shown the moment you land
 * on the app (cold load / hard refresh): the StarCi lockup centred over the page
 * background, with the same 3px brand-pink line trickling across the top as
 * {@link TopLoader} (one accent bar, two surfaces).
 *
 * It paints in the server HTML (so it's there before any JS), then fades out once
 * the client has mounted ΓÇö plus a short minimum so it doesn't blink on a fast
 * boot. Self-managing: mounted once in {@link InnerLayout}, renders `null` when
 * done. Honours `prefers-reduced-motion` (static bar, no trickle). Owns all of its style.
 * @see Story: .storybook/stories/blocks/layout/AppSplash/AppSplash.stories
 */
export const _AppSplash = ({ loadingLabel }: AppSplashProps) => {
    const [leaving, setLeaving] = useState(false)
    const [gone, setGone] = useState(false)

    useEffect(() => {
        const timer = setTimeout(() => setLeaving(true), MIN_VISIBLE_MS)
        return () => clearTimeout(timer)
    }, [])

    useEffect(() => {
        if (!leaving) {
            return
        }
        const timer = setTimeout(() => setGone(true), FADE_MS)
        return () => clearTimeout(timer)
    }, [leaving])

    if (gone) {
        return null
    }

    return (
        <div
            role="status"
            aria-label={loadingLabel}
            className={cn(
                "fixed inset-0 z-[70] flex flex-col items-center justify-center gap-6 bg-background transition-opacity",
                leaving ? "pointer-events-none opacity-0" : "opacity-100",
            )}
            style={{ transitionDuration: `${FADE_MS}ms` }}
        >
            <div className="pointer-events-none fixed inset-x-0 top-0 h-[3px] overflow-hidden">
                <div
                    className="app-splash-bar h-full bg-accent"
                    style={{ animation: "appSplashTrickle 2.4s ease-in-out infinite" }}
                />
            </div>
            <BrandLogo size="lg" />
            <Typography type="body-sm" color="muted">
                {loadingLabel}
            </Typography>
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useRef } from "react"
import { cn } from "@heroui/react"
import type { PointerEvent as ReactPointerEvent, ReactNode } from "react"

/** Height (px) of the grabber handle strip above the peek row. */
const GRABBER_HEIGHT = 26
/** Fallback peek height (px) before the peek row has measured. */
const PEEK_FALLBACK = 52
/** Fraction of the viewport the expanded sheet may occupy at most. */
const MAX_VIEWPORT_FRACTION = 0.6
/** Drag distance (px) under which a pointer gesture counts as a tap (toggle), not a drag. */
const TAP_THRESHOLD = 5

/** Props for the {@link ConnectSheet} block. */
export interface ConnectSheetProps {
    /** Whether the sheet is expanded (controlled ΓÇö the feature owns snap state). */
    open: boolean
    /** Fired when the user drags/taps to change the snap (or taps the peek row). */
    onOpenChange: (open: boolean) => void
    /** Collapsed PEEK row content ΓÇö always visible (status + summary + optional action). */
    peek: ReactNode
    /** Expanded BODY content, revealed on drag-up / tap. */
    children: ReactNode
    /** Accessible label for the drag/toggle grabber. */
    toggleLabel: string
}

/**
 * A PERSISTENT, draggable bottom sheet docked to the bottom of a `relative`
 * parent (NOT a modal ΓÇö no backdrop, the content above stays interactive). Two
 * snap points: COLLAPSED (grabber + peek row only) <-> EXPANDED (peek + body,
 * capped at {@link MAX_VIEWPORT_FRACTION} of the viewport). Drag the grabber <->
 * to resize then snap on release; a small drag (< {@link TAP_THRESHOLD}) or a tap
 * on the peek row toggles. `open` is CONTROLLED so the feature can auto-snap per
 * phase (e.g. expand while waiting, collapse once connected). Self-contained
 * pointer drag ΓÇö no framer-motion dependency. Card-like -> `rounded-t-3xl`.
 *
 * Refs: dock = `StickyBottomBar`; drag = `CollapsibleSidebar`.
 * @param props - {@link ConnectSheetProps}
 */
export const ConnectSheet = ({
    open,
    onOpenChange,
    peek,
    children,
    toggleLabel}: ConnectSheetProps) => {
    const sheetRef = useRef<HTMLDivElement>(null)
    const peekRef = useRef<HTMLDivElement>(null)
    const bodyRef = useRef<HTMLDivElement>(null)
    const drag = useRef<{ startY: number; startH: number; moved: boolean } | null>(null)
    // set true after a DRAG so the trailing synthetic click (fired on pointerup)
    // doesn't also toggle ΓÇö a tap (no drag) falls through to the native click.
    const suppressClick = useRef(false)

    const collapsedHeight = useCallback(
        () => GRABBER_HEIGHT + (peekRef.current?.offsetHeight ?? PEEK_FALLBACK),
        [],
    )
    const expandedHeight = useCallback(() => {
        const cap = typeof window !== "undefined"
            ? Math.round(window.innerHeight * MAX_VIEWPORT_FRACTION)
            : 480
        const wanted = collapsedHeight() + (bodyRef.current?.scrollHeight ?? 0) + 16
        return Math.max(collapsedHeight(), Math.min(wanted, cap))
    }, [collapsedHeight])

    const applyHeight = useCallback((isOpen: boolean, instant = false) => {
        const el = sheetRef.current
        if (!el) {
            return
        }
        if (instant) {
            el.style.transition = "none"
        }
        el.style.height = `${isOpen ? expandedHeight() : collapsedHeight()}px`
        if (instant) {
            requestAnimationFrame(() => { el.style.transition = "" })
        }
    }, [collapsedHeight, expandedHeight])

    // snap to the controlled `open` state, and re-measure when the peek/body
    // content changes (per-phase) or the viewport resizes.
    useEffect(() => { applyHeight(open) })
    useEffect(() => {
        const onResize = () => applyHeight(open, true)
        window.addEventListener("resize", onResize)
        return () => window.removeEventListener("resize", onResize)
    }, [open, applyHeight])

    const onPointerDown = (event: ReactPointerEvent<HTMLButtonElement>) => {
        event.currentTarget.setPointerCapture(event.pointerId)
        drag.current = {
            startY: event.clientY,
            startH: sheetRef.current?.getBoundingClientRect().height ?? collapsedHeight(),
            moved: false,
        }
        if (sheetRef.current) {
            sheetRef.current.style.transition = "none"
        }
    }
    const onPointerMove = (event: ReactPointerEvent<HTMLButtonElement>) => {
        const current = drag.current
        if (!current || !sheetRef.current) {
            return
        }
        const delta = current.startY - event.clientY
        if (Math.abs(delta) > TAP_THRESHOLD) {
            current.moved = true
        }
        const height = Math.max(collapsedHeight(), Math.min(current.startH + delta, expandedHeight()))
        sheetRef.current.style.height = `${height}px`
    }
    const onPointerUp = () => {
        const current = drag.current
        if (!current || !sheetRef.current) {
            return
        }
        drag.current = null
        sheetRef.current.style.transition = ""
        if (!current.moved) {
            // a TAP ΓÇö let the native button click toggle (keyboard-accessible path).
            return
        }
        // a DRAG ΓÇö snap by threshold; suppress the trailing synthetic click.
        suppressClick.current = true
        const height = sheetRef.current.getBoundingClientRect().height
        const midpoint = (collapsedHeight() + expandedHeight()) / 2
        const next = height > midpoint
        onOpenChange(next)
        applyHeight(next)
    }

    // native click = keyboard (Enter/Space) + tap toggle; skipped right after a drag.
    const onToggleClick = () => {
        if (suppressClick.current) {
            suppressClick.current = false
            return
        }
        onOpenChange(!open)
        applyHeight(!open)
    }

    return (
        <div
            ref={sheetRef}
            className={cn(// BORDER delineates the docked sheet from the content above ΓÇö NOT a
                // shadow: `shadow-surface` casts DOWNWARD + is very subtle, so on a
                // bottom-docked sheet it can't mark the top seam (axis-1 ┬º16: when a
                // shadow can't delineate, use a border instead). No ad-hoc shadow-md ΓÇö
                // the design system only has surface/field/overlay shadow tokens.
                "absolute inset-x-0 bottom-0 z-30 flex flex-col overflow-hidden rounded-t-3xl border border-default bg-surface",
                "[transition:height_280ms_cubic-bezier(0.32,0.72,0,1)]")}
            style={{ height: GRABBER_HEIGHT + PEEK_FALLBACK }}
        >
            <button
                type="button"
                aria-label={toggleLabel}
                aria-expanded={open}
                onPointerDown={onPointerDown}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerUp}
                onPointerCancel={onPointerUp}
                onClick={onToggleClick}
                className="flex shrink-0 cursor-grab touch-none items-center justify-center py-2 outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent active:cursor-grabbing"
            >
                <span className="h-[5px] w-9 rounded-full bg-default" />
            </button>
            <div ref={peekRef} className="shrink-0 px-4 pb-3">
                {peek}
            </div>
            <div
                ref={bodyRef}
                className={cn(
                    "min-h-0 flex-1 overflow-auto px-4 pb-5",
                    !open && "pointer-events-none opacity-40",
                )}
            >
                {children}
            </div>
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useRef,
    useState,
} from "react"
import {
    ScrollShadow,
    cn,
} from "@heroui/react"
import {
    motion,
    type PanInfo,
} from "framer-motion"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link DragScrollArea}. */
export interface DragScrollAreaProps extends WithClassNames<undefined> {
    /** Scrollable content. */
    children: React.ReactNode
    /** Hide the native scrollbar (default true). */
    hideScrollBar?: boolean
    /** ScrollShadow edge fade size in px. */
    size?: number
}

/**
 * Vertical scroll region with hidden scrollbar and Framer Motion pointer pan.
 *
 * Wheel/trackpad/touch scroll still work; `onPan` maps drag delta to `scrollTop`
 * so Windows users can scroll when the bar is hidden. Cursor is `grab` /
 * `grabbing` while panning. Presentational only.
 * @param props - {@link DragScrollAreaProps}
 */
export const DragScrollArea = ({
    className,
    children,
    hideScrollBar = true,
    size = 40,
}: DragScrollAreaProps) => {
    const scrollRef = useRef<HTMLDivElement>(null)
    const [isPanning, setIsPanning] = useState(false)

    const onPan = useCallback((_event: PointerEvent, info: PanInfo) => {
        const element = scrollRef.current
        if (!element) {
            return
        }
        element.scrollTop -= info.delta.y
    }, [])

    return (
        <ScrollShadow
            ref={scrollRef}
            hideScrollBar={hideScrollBar}
            size={size}
            className={cn("overflow-y-auto", className)}
        >
            <motion.div
                className={cn(
                    "min-h-min select-none",
                    isPanning ? "cursor-grabbing" : "cursor-grab",
                )}
                onPanStart={() => setIsPanning(true)}
                onPan={onPan}
                onPanEnd={() => setIsPanning(false)}
            >
                {children}
            </motion.div>
        </ScrollShadow>
    )
}

import React from "react"
import type { ReactNode } from "react"

/** Props for the {@link PageContainer} block. */
export interface PageContainerProps {
    /** Page content, composed by the caller. */
    children: ReactNode
}

/**
 * Standard page shell ΓÇö full width of the parent with a right gutter + vertical
 * rhythm. No `mx-auto` centering and no left padding (flush start). Owns page
 * spacing so features (which must not use `p-*`) compose inside it.
 *
 * @param props - {@link PageContainerProps}
 * @see Story: .storybook/stories/blocks/layout/PageContainer/PageContainer.stories
 */
export const PageContainer = ({ children }: PageContainerProps) => {
    return (
        <div className="w-full py-16 pr-4 @app-sm:pr-6 @app-lg:pr-8">
            {children}
        </div>
    )
}

import React from "react"
import { cn, Typography } from "@heroui/react"
import type { ReactNode } from "react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/**
 * Props for the {@link PageHeader} block.
 *
 * A tier-3 presentational block ΓÇö every piece of content arrives via props.
 * No store reads, no SWR, no translation hooks.
 */
export interface PageHeaderProps extends WithClassNames<undefined> {
    /**
     * Primary page or section title. Rendered at `text-xl font-medium` in the
     * foreground tone. Accept a string or any inline React node (e.g. a
     * title with an inline badge).
     */
    title: ReactNode
    /**
     * Optional supporting description placed directly below the title. Rendered
     * at `text-sm` in the muted tone. Omit when the title is self-explanatory.
     */
    description?: ReactNode
    /**
     * Optional breadcrumb row rendered above the title row. Accepts any node ΓÇö
     * typically a `<Breadcrumbs>` HeroUI component or a plain anchor chain.
     * Rendered at a smaller scale so it visually precedes the title hierarchy.
     */
    breadcrumb?: ReactNode
    /**
     * Optional right-aligned slot for action controls (e.g. `<Button>` or a
     * group of buttons). Rendered `shrink-0` so it never compresses the title
     * column.
     */
    actions?: ReactNode
    /**
     * Optional meta row placed BELOW the title/description ΓÇö typically a row of
     * stat/meta chips ("24 Modules - 87 Content Items ΓÇª"). Rendered `gap-3` from the
     * title block. Omit when the header carries no stats.
     */
    meta?: ReactNode
    /**
     * Title scale. `"page"` (default) = `Typography.Heading` level 3 ΓÇö a route's
     * OWN page title. `"compact"` = body-size bold, for a header that labels a
     * PANE/PHASE inside an existing page shell, where a full page title
     * out-shouts the surface it sits on (e.g. the playground Setup pane, which
     * already lives under the session header + Setup/Lab tab strip).
     */
    size?: "page" | "compact"
    /**
     * Caller identity to wear on this block's root instead of its own ΓÇö pass this
     * when a layout/page uses PageHeader as its root element.
     */
    identity?: CallerIdentity
}

/**
 * Page/section header block. Renders an optional breadcrumb row above a flex
 * row that places a stacked title + description on the left and optional action
 * controls on the right.
 *
 * This block carries no card wrapper ΓÇö the caller places it directly inside a
 * page layout or wraps it in a `SectionCard` when a framed surface is required.
 *
 * @param props - See {@link PageHeaderProps}.
 * @returns The rendered page header element.
 *
 * @example
 * <PageHeader
 *   breadcrumb={<Breadcrumbs .../>}
 *   title="Manage Users"
 *   description="View and edit all registered learners."
 *   actions={<Button>Invite</Button>}
 * />
 * @see Story: .storybook/stories/blocks/layout/PageHeader/PageHeader.stories
 */
export const PageHeader = ({
    title,
    description,
    breadcrumb,
    actions,
    meta,
    size = "page",
    className,
    identity,
}: PageHeaderProps) => {
    return (
        // outer gap-3: breadcrumb <-> title-block <-> meta (different header tiers);
        // title <-> description stay a tight gap-2 pair inside the title block.
        <div
            {...resolveIdentity(identity, { tier: "block", name: "PageHeader" })}
            className={cn("flex flex-col gap-3", className)}
        >
            {/* Breadcrumb row ΓÇö rendered only when provided, sits above the main title row */}
            {breadcrumb ? (
                <div>{breadcrumb}</div>
            ) : null}

            {/* Main row: title+description stack on the left, actions pinned to the right */}
            <div className="flex items-start justify-between gap-3">
                {/* Left column: stacked title and optional description */}
                <div className="flex min-w-0 flex-col gap-2">
                    {size === "compact" ? (
                        <Typography type="body" weight="bold">{title}</Typography>
                    ) : (
                        <Typography.Heading level={3} weight="bold">{title}</Typography.Heading>
                    )}
                    {description ? (
                        // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                        <Typography type="body-sm" color="muted" className="line-clamp-2 @app-sm:line-clamp-none">
                            {description}
                        </Typography>
                    ) : null}
                </div>

                {/* Right slot: shrink-0 prevents action buttons from being squeezed */}
                {actions ? (
                    <div className="shrink-0">{actions}</div>
                ) : null}
            </div>

            {/* Meta row: stat/meta chips below the title block (gap-3 from outer) */}
            {meta ? (
                <div>{meta}</div>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
    type ReactNode,
} from "react"
import { cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for the {@link ResizableRail} block. */
export interface ResizableRailProps extends WithClassNames<undefined> {
    /** Rail content (e.g. the content-map tree). */
    children: ReactNode
    /** localStorage key the chosen width is persisted under. */
    storageKey: string
    /** Initial width in px before any persisted value loads. */
    defaultWidth?: number
    /** Smallest allowed width in px. */
    minWidth?: number
    /** Largest allowed width in px. */
    maxWidth?: number
    /** Accessible name for the drag handle (separator). */
    ariaLabel?: string
    /**
     * Which edge the drag handle sits on. `"right"` (default) suits a LEFT rail
     * (drag right = wider). `"left"` suits a RIGHT rail (handle on the inner edge,
     * drag left = wider) ΓÇö e.g. a right-docked chat panel.
     */
    handleSide?: "left" | "right"
    /**
     * Publish the live width to this CSS custom property on `:root` (e.g.
     * `"--app-rail-w"`), resetting it to `0px` while unmounted.
     *
     * `position: fixed` chrome cannot be constrained by a docked rail through CSS
     * alone: fixed elements resolve against the VIEWPORT, and the obvious lever
     * (`contain: layout` on the sibling column) re-anchors them to that column's
     * FULL box ΓÇö which is page-tall, so anything `bottom-*` lands thousands of
     * pixels below the fold. Exporting the width instead lets each piece of chrome
     * keep viewport anchoring and simply subtract the rail:
     * `right-[var(--app-rail-w,0px)]`.
     */
    widthVar?: string
}

/**
 * A side rail whose width the reader can drag to resize, with the chosen width
 * persisted to `localStorage`. A thin handle pinned to the right edge is the
 * splitter: drag (pointer) or focus + Arrow keys to resize; the surrounding
 * content reflows. Tier-3 block ΓÇö owns the handle styling + the ephemeral width
 * state; the rail body arrives via `children` (no store / SWR / data props).
 *
 * Positioning (sticky / hidden-on-mobile / max-height) is supplied by the caller
 * through `className`; this block only owns the width + the handle. The root is
 * NOT forced to `position: relative` ΓÇö that would override a caller's
 * `@app-lg:sticky`; the handle instead anchors to whatever positioned context the
 * caller establishes (the sticky rail itself).
 *
 * @param props - {@link ResizableRailProps}
 * @see Story: .storybook/stories/blocks/layout/ResizableRail/ResizableRail.stories
 */
export const ResizableRail = ({
    children,
    storageKey,
    defaultWidth = 320,
    minWidth = 256,
    maxWidth = 560,
    ariaLabel,
    handleSide = "right",
    widthVar,
    className,
}: ResizableRailProps) => {
    // a left-edge handle widens when dragged LEFT (negative deltaX), so flip the sign.
    const dir = handleSide === "left" ? -1 : 1
    const [width, setWidth] = useState(defaultWidth)
    /** Latest width mirror so pointer-up can persist without a stale closure. */
    const widthRef = useRef(defaultWidth)
    /** Drag origin captured on pointer-down. */
    const dragRef = useRef<{ startX: number; startWidth: number } | null>(null)

    const clamp = useCallback(
        (value: number) => Math.min(Math.max(value, minWidth), maxWidth),
        [minWidth, maxWidth],
    )

    /** Commit a new width to state + the persistence ref. */
    const applyWidth = useCallback(
        (value: number) => {
            const next = clamp(value)
            widthRef.current = next
            setWidth(next)
        },
        [clamp],
    )

    // Hydrate the persisted width on mount (client-only; the SSR/first paint uses
    // `defaultWidth` so markup matches and there is no hydration mismatch).
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored === null) {
            return
        }
        const parsed = Number(stored)
        if (!Number.isNaN(parsed)) {
            applyWidth(parsed)
        }
    }, [storageKey, applyWidth])

    // Re-clamp when the BOUNDS move under us. `clamp` alone is not enough: it only
    // runs on hydrate/drag/keydown, so a caller that narrows `maxWidth` (e.g. the
    // window shrank, and the rail must not squeeze the content column below its
    // layout breakpoint) would keep rendering the old, now-illegal width until the
    // reader happens to drag again. Deliberately NOT persisted ΓÇö the stored width is
    // the reader's PREFERENCE, and a temporary small window should not overwrite it.
    useEffect(() => {
        const bounded = clamp(widthRef.current)
        if (bounded !== widthRef.current) {
            widthRef.current = bounded
            setWidth(bounded)
        }
    }, [clamp])

    // Publish the live width so viewport-anchored `fixed` chrome can dodge the rail.
    // Reset to `0px` on unmount, NOT delete: consumers read it with a `0px` fallback,
    // but a stale non-zero value would leave every FAB floating in from the edge
    // after the rail closes.
    useEffect(() => {
        if (!widthVar) {
            return
        }
        const root = document.documentElement
        root.style.setProperty(widthVar, `${Math.round(width)}px`)
        return () => root.style.setProperty(widthVar, "0px")
    }, [widthVar, width])

    const onPointerDown = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
        event.preventDefault()
        event.currentTarget.setPointerCapture(event.pointerId)
        dragRef.current = { startX: event.clientX, startWidth: widthRef.current }
        document.body.style.cursor = "col-resize"
        document.body.style.userSelect = "none"
    }, [])

    const onPointerMove = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
        if (!dragRef.current) {
            return
        }
        applyWidth(dragRef.current.startWidth + dir * (event.clientX - dragRef.current.startX))
    }, [applyWidth, dir])

    const onPointerUp = useCallback((event: React.PointerEvent<HTMLDivElement>) => {
        if (!dragRef.current) {
            return
        }
        dragRef.current = null
        event.currentTarget.releasePointerCapture(event.pointerId)
        document.body.style.removeProperty("cursor")
        document.body.style.removeProperty("user-select")
        window.localStorage.setItem(storageKey, String(Math.round(widthRef.current)))
    }, [storageKey])

    const onKeyDown = useCallback((event: React.KeyboardEvent<HTMLDivElement>) => {
        const step = event.shiftKey ? 32 : 16
        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") {
            return
        }
        event.preventDefault()
        applyWidth(widthRef.current + (event.key === "ArrowLeft" ? -step : step))
        window.localStorage.setItem(storageKey, String(Math.round(widthRef.current)))
    }, [applyWidth, storageKey])

    return (
        <div className={cn(className)} style={{ width }}>
            {children}
            {/* splitter: a thin line at the chosen edge that thickens to accent on hover/drag */}
            <div
                role="separator"
                aria-orientation="vertical"
                aria-label={ariaLabel}
                tabIndex={0}
                onPointerDown={onPointerDown}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerUp}
                onKeyDown={onKeyDown}
                className={cn(
                    "group absolute inset-y-0 z-20 flex w-3 cursor-col-resize items-stretch justify-center outline-none",
                    handleSide === "left" ? "left-0 -translate-x-1/2" : "right-0 translate-x-1/2",
                )}
            >
                <span className="h-full w-px bg-separator transition-colors group-hover:bg-accent group-focus-visible:bg-accent" />
            </div>
        </div>
    )
}

import React, { useEffect, useRef, useState } from "react"
import { ArrowsClockwiseIcon } from "@phosphor-icons/react"
import { toast } from "@/modules/toast/toast"

/** Grace period before a drop is surfaced ΓÇö a sub-2s blip never flashes a toast. */
const DOWN_DELAY_MS = 2000
/** How long the "reconnected" confirmation lingers before the toast hides. */
const RECOVERED_MS = 1500

/** Debounced display phase of the status toast. */
type Phase = "hidden" | "down" | "recovered"

/** Props for {@link _SocketConnectionStatus} ΓÇö presentational; toast copy already resolved. */
export interface SocketConnectionStatusProps {
    /** Whether any realtime socket is currently down (from `useAnySocketDown`). */
    anyDown: boolean
    /** Already-localized "reconnecting" toast message. */
    reconnectingLabel: string
    /** Already-localized "reconnected" toast message. */
    reconnectedLabel: string
}

/**
 * SocketConnectionStatus ΓÇö a global, non-blocking "connection lost / reconnecting"
 * toast (same timing as the old Google Docs-style pill). Appears only when a
 * realtime socket drops for longer than {@link DOWN_DELAY_MS}, stays open while
 * down (`timeout: 0`), then auto-confirms "reconnected" and dismisses on recovery.
 *
 * The app keeps working over HTTP, so this is purely informational. Mounted once
 * in {@link import("@/app/InnerLayout").InnerLayout}; renders nothing itself ΓÇö
 * status is pushed through the shared {@link toast} queue (`ToastProvider`).
 * @see Story: .storybook/stories/blocks/layout/SocketConnectionStatus/SocketConnectionStatus.stories
 *
 * @param props - {@link SocketConnectionStatusProps}
 */
export const _SocketConnectionStatus = ({ anyDown, reconnectingLabel, reconnectedLabel }: SocketConnectionStatusProps) => {
    const [phase, setPhase] = useState<Phase>("hidden")

    const downTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
    const recoveredTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
    /** Latest phase, read inside async timers without re-subscribing them. */
    const phaseRef = useRef<Phase>("hidden")
    phaseRef.current = phase
    /** Key of the persistent "down" toast ΓÇö closed when we leave that phase. */
    const downToastKey = useRef<string | null>(null)

    // React to the socket up/down signal: arm a grace timer on drop, confirm on recovery.
    useEffect(() => {
        if (anyDown) {
            if (recoveredTimer.current) {
                clearTimeout(recoveredTimer.current)
                recoveredTimer.current = null
            }
            // wait out the grace period ΓÇö a brief blip should never show the toast
            if (!downTimer.current) {
                downTimer.current = setTimeout(() => {
                    downTimer.current = null
                    setPhase("down")
                }, DOWN_DELAY_MS)
            }
            return
        }
        // back up ΓÇö cancel a pending grace timer
        if (downTimer.current) {
            clearTimeout(downTimer.current)
            downTimer.current = null
        }
        // only celebrate "reconnected" if the drop was actually surfaced
        if (phaseRef.current === "down") {
            setPhase("recovered")
        } else {
            setPhase("hidden")
        }
    }, [anyDown])

    // After the "reconnected" confirmation lingers, hide.
    useEffect(() => {
        if (phase !== "recovered") {
            return
        }
        recoveredTimer.current = setTimeout(() => {
            recoveredTimer.current = null
            setPhase("hidden")
        }, RECOVERED_MS)
        return () => {
            if (recoveredTimer.current) {
                clearTimeout(recoveredTimer.current)
                recoveredTimer.current = null
            }
        }
    }, [phase])

    // Drive the toast queue from phase ΓÇö down is persistent; recovered auto-dismisses.
    useEffect(() => {
        if (phase === "down") {
            const key = toast.warning(reconnectingLabel, {
                timeout: 0,
                indicator: (
                    <ArrowsClockwiseIcon
                        aria-hidden
                        focusable="false"
                        className="size-6 animate-spin text-warning-soft-foreground"
                    />
                ),
            })
            downToastKey.current = typeof key === "string" ? key : null
            return () => {
                if (downToastKey.current) {
                    toast.close(downToastKey.current)
                    downToastKey.current = null
                }
            }
        }

        if (phase === "recovered") {
            toast.success(reconnectedLabel, {
                timeout: RECOVERED_MS,
            })
        }

        return undefined
    }, [phase, reconnectingLabel, reconnectedLabel])

    // Tidy timers on unmount.
    useEffect(
        () => () => {
            if (downTimer.current) {
                clearTimeout(downTimer.current)
            }
            if (recoveredTimer.current) {
                clearTimeout(recoveredTimer.current)
            }
            if (downToastKey.current) {
                toast.close(downToastKey.current)
                downToastKey.current = null
            }
        },
        [],
    )

    return null
}

