import React from "react"
import {
    Badge,
    cn,
} from "@heroui/react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link _UserSummary} ΓÇö presentational; the display fields already resolved. */
export interface UserSummaryProps extends WithClassNames<undefined> {
    /** Already-truncated display username. */
    truncatedUsername: string
    /** Avatar image, or `undefined` for the generated fallback. */
    avatar?: string | null
    /** Avatar seed material (email preferred, else username). */
    avatarSeed?: string
    /** Raw username (avatar generation input). */
    username?: string
    /** The signed-in user's email. */
    email?: string
}

/**
 * Header panel for authenticated users: avatar, truncated username, email,
 * and a notification bell badge.
 *
 * @param props - {@link UserSummaryProps}
 */
export const _UserSummary = ({ truncatedUsername, avatar, avatarSeed, username, email, className }: UserSummaryProps) => (
    <div className={cn("flex items-center justify-between gap-6", className)}>
        <div className="flex items-center gap-2">
            <UserAvatar
                className="cursor-pointer"
                username={username}
                avatar={avatar}
                seed={avatarSeed}
            />
            <div className="flex flex-col gap-0">
                <div className="text-sm">
                    {truncatedUsername}
                </div>
                <div className="text-xs text-muted">{email}</div>
            </div>
        </div>
        <Badge size="sm" className="border-0" content="0" color="accent">
            <BellIcon className="size-6 text-divider" />
        </Badge>
    </div>
)

import React from "react"
import {
    Dropdown,
    DropdownPopover,
    Separator,
    cn,
} from "@heroui/react"
import { AccountTrigger } from "./AccountTrigger"
import { UserSummary } from "./UserSummary"
import { AuthActions } from "./AuthActions"
import { MenuList } from "./MenuList"
import { AppearanceRow } from "./AppearanceRow"
import { LogoutMenu } from "./LogoutMenu"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link _AccountMenuDropdown} ΓÇö presentational; open-state + auth already resolved. */
export interface AccountMenuDropdownProps extends WithClassNames<{
    /** Optional class applied to the dropdown container. */
    menuContainer?: string
}> {
    /** Whether the dropdown popover is open. */
    isOpen: boolean
    /** Fired with the new open state (backdrop click, Escape, trigger press). */
    onOpenChange: (open: boolean) => void
    /** `true` ΓåÆ show {@link UserSummary}; `false` ΓåÆ show {@link AuthActions}. */
    isAuthenticated: boolean
}

/**
 * AccountMenuDropdown ΓÇö navbar account menu.
 *
 * Arrangement only: every section below (trigger, summary/auth, menu list,
 * appearance row, logout) is itself a self-contained CONNECTED block that
 * fetches/dispatches its own data ΓÇö this component only lays them out and
 * owns the popover's open state + the summary/auth-actions switch.
 *
 * @param props - {@link AccountMenuDropdownProps}
 */
export const _AccountMenuDropdown = ({ isOpen, onOpenChange, isAuthenticated, classNames }: AccountMenuDropdownProps) => (
    <Dropdown
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        className={cn(classNames?.menuContainer)}
    >
        {/** Dropdown trigger */}
        <AccountTrigger />
        {/** Dropdown content */}
        <DropdownPopover placement="bottom right" className="min-w-[300px] overflow-hidden">
            <div className="p-3">
                {isAuthenticated ? (
                    <UserSummary />
                ) : (
                    <AuthActions />
                )}
            </div>
            <Separator />
            <MenuList />
            <AppearanceRow />
            <Separator />
            <LogoutMenu />
        </DropdownPopover>
    </Dropdown>
)

"use client"

import React, {
    useCallback,
} from "react"
import {
    cn,
    Link,
} from "@heroui/react"
import {
    pathConfig,
} from "@/resources/path"
import {
    useRouter,
} from "@/i18n/navigation"
import { LogoMark } from "@/components/svg/LogoMark"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Props for {@link Logo}.
 */
export type LogoProps = WithClassNames<undefined>

/**
 * Logo ΓÇö application brand mark that routes home when pressed.
 *
 * `"use client"` for the router press handler.
 * @param props - optional container class name
 */
export const Logo = ({ className }: LogoProps) => {
    const router = useRouter()

    /** Navigate to the localized home route. */
    const onPress = useCallback(
        () => router.push(pathConfig().locale().build()),
        [
            router,
        ],
    )
    return (
        <Link
            onPress={onPress}
            className={cn(className)}
        >
            <LogoMark />
        </Link>
    )
}

import type { IconComponent } from "@/types"
import { GlobeIcon as TranslateIcon, PaintBrushIcon } from "@phosphor-icons/react"
import React from "react"
import {
    Link,
    cn,
} from "@heroui/react"
