import {
    BellIcon,
    ChecksIcon as CheckDoubleIcon,
} from "@phosphor-icons/react"
import React, { useState } from "react"
import {
    Badge,
    Button,
    Popover,
    PopoverContent,
    Separator,
    Spinner,
    cn,
} from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Largest unread count rendered verbatim on the badge before showing "9+". */
const MAX_BADGE = 9

/** One notification row, already resolved for display. */
export interface NotificationBellItem {
    /** Stable id ΓÇö the row's React key. */
    id: string
    /** `false` ΓåÆ the row shows the unread dot + tint. */
    isRead: boolean
    /** Already-localized title line. */
    titleText: string
    /** Already-localized body line; `null` hides it. */
    bodyText: string | null
    /** Already-localized relative time ("3h ago"). */
    relativeLabel: string
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Props for {@link _NotificationBell} ΓÇö presentational; all data + labels already resolved. */
export interface NotificationBellProps extends WithClassNames<undefined> {
    /** `false` ΓåÆ renders nothing (the bell is only meaningful for a signed-in viewer). */
    isAuthenticated: boolean
    /** The recent notification rows, already resolved. */
    items: Array<NotificationBellItem>
    /** Unread count driving the badge (capped display at {@link MAX_BADGE}+). */
    unreadCount: number
    /** `true` while the FIRST load is in flight (no items yet). */
    isLoading: boolean
    /** Already-localized bell trigger aria-label ("Notifications"). */
    bellAriaLabel: string
    /** Already-localized popover header title. */
    titleLabel: string
    /** Already-localized "Mark all read" action label. */
    markAllReadLabel: string
    /** Already-localized empty-state message. */
    emptyLabel: string
    /** Fired when "Mark all read" is pressed. */
    onMarkAllRead: () => void
}

/**
 * NotificationBell ΓÇö navbar bell with an unread-count badge and a popover list.
 *
 * @param props - {@link NotificationBellProps}
 */
export const _NotificationBell = ({
    isAuthenticated,
    items,
    unreadCount,
    isLoading,
    bellAriaLabel,
    titleLabel,
    markAllReadLabel,
    emptyLabel,
    onMarkAllRead,
    className,
}: NotificationBellProps) => {
    const [isOpen, setOpen] = useState(false)

    // the bell is only meaningful for an authenticated viewer
    if (!isAuthenticated) {
        return null
    }

    /** Badge label, capped at {@link MAX_BADGE} (e.g. "9+"). */
    const badgeLabel = unreadCount > MAX_BADGE ? `${MAX_BADGE}+` : `${unreadCount}`

    return (
        <Popover isOpen={isOpen} onOpenChange={setOpen}>
            <Button
                isIconOnly
                variant="tertiary"
                className={cn("rounded-full", className)}
                aria-label={bellAriaLabel}
            >
                {unreadCount > 0 ? (
                    <Badge.Anchor>
                        <BellIcon className="size-5" />
                        <Badge size="sm" color="danger">{badgeLabel}</Badge>
                    </Badge.Anchor>
                ) : (
                    <BellIcon className="size-5" />
                )}
            </Button>
            <PopoverContent placement="bottom right" className="w-[360px] overflow-hidden p-0">
                {/* header: title + mark-all-read action */}
                <div className="flex items-center justify-between gap-3 p-3">
                    <span className="text-sm font-semibold text-foreground">
                        {titleLabel}
                    </span>
                    {unreadCount > 0 ? (
                        <Button
                            size="sm"
                            variant="tertiary"
                            onPress={onMarkAllRead}
                            className="gap-2"
                        >
                            <CheckDoubleIcon className="size-5" />
                            <span className="text-xs">{markAllReadLabel}</span>
                        </Button>
                    ) : null}
                </div>
                <Separator />

                {/* body: loading / empty / list */}
                {isLoading && items.length === 0 ? (
                    <div className="flex items-center justify-center p-6">
                        <Spinner size="sm" />
                    </div>
                ) : items.length === 0 ? (
                    <div className="p-6 text-center text-sm text-muted">
                        {emptyLabel}
                    </div>
                ) : (
                    <div className="flex max-h-[420px] flex-col overflow-y-auto">
                        {items.map((notification) => (
                            <button
                                key={notification.id}
                                type="button"
                                onClick={() => {
                                    setOpen(false)
                                    notification.onPress()
                                }}
                                className={cn(
                                    "flex flex-col gap-2 px-3 py-3 text-left hover:bg-default/40",
                                    !notification.isRead && "bg-primary/5",
                                )}
                            >
                                <div className="flex items-center gap-2">
                                    {!notification.isRead ? (
                                        <span className="size-2 shrink-0 rounded-full bg-primary" />
                                    ) : null}
                                    <span className="flex-1 text-sm font-medium text-foreground">
                                        {notification.titleText}
                                    </span>
                                </div>
                                {notification.bodyText ? (
                                    <span className="text-xs text-muted">
                                        {notification.bodyText}
                                    </span>
                                ) : null}
                                <span className="text-[11px] text-muted">
                                    {notification.relativeLabel}
                                </span>
                            </button>
                        ))}
                    </div>
                )}
            </PopoverContent>
        </Popover>
    )
}

"use client"

import React, {
    useEffect,
} from "react"
import {
    Logo,
} from "./Logo"
import {
    AccountMenuDropdown,
} from "./AccountMenuDropdown"
import {
    NavLinks,
} from "./NavLinks"
import {
    SearchButton,
} from "./SearchButton"
import {
    NotificationBell,
} from "./NotificationBell"
import { useSearchOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * Props for {@link Navbar}.
 */
export type NavbarProps = Record<string, never>
/**
 * Navbar ΓÇö top application navigation bar.
 *
 * Container: owns the Ctrl/Cmd+K search shortcut and renders the logo,
 * self-navigating links, search trigger, and the account dropdown.
 * `"use client"` for hooks + keyboard handling.
 * @param props - optional root class name
 */
export const Navbar = () => {
    const { open: openSearch } = useSearchOverlayState()

    // register the global Ctrl/Cmd+K shortcut to open the search overlay
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key.toLowerCase() === "k"
            if (!isK) return
            if (!(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            openSearch()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [openSearch])

    return (
        <nav className={"sticky top-0 z-50 h-16 min-h-16 border-b bg-background"}>
            <div className="mx-auto flex h-full w-full items-center justify-between px-3">
                <div className="flex items-center gap-6">
                    <Logo className="flex-1 justify-start" />
                    <NavLinks />
                </div>

                <div className="flex items-center justify-end gap-3">
                    <SearchButton />
                    <NotificationBell />
                    <AccountMenuDropdown />
                </div>
            </div>
        </nav>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { useCallback } from "react"
import type { RendererTypeOption } from "@/modules/types/admin-mpeg-dash-test"
import type { VideoRendererType } from "@/modules/types/enums/video-renderer-type"

/** Props for {@link RendererTypeButton}. */
export interface RendererTypeButtonProps {
    /** Option metadata to render. */
    option: RendererTypeOption
    /** Whether this option is currently selected. */
    isActive: boolean
    /** Selects this option's renderer type. */
    onSelect: (type: VideoRendererType) => void
}

/**
 * Single renderer-type selector button (icon + label + description).
 * @param props.option - Option metadata to render.
 * @param props.isActive - Whether this option is the active renderer type.
 * @param props.onSelect - Called with this option's type when pressed.
 */
export const RendererTypeButton = ({
    option,
    isActive,
    onSelect}: RendererTypeButtonProps) => {
    const onPress = useCallback(
        () => onSelect(option.type),
        [onSelect, option.type],
    )

    return (
        <button
            onClick={onPress}
            className={cn(
                "flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-medium transition-all",
                isActive
                    ? `bg-gradient-to-r ${option.color} text-white shadow-lg`
                    : "bg-slate-700/50 text-slate-300 hover:bg-slate-700",
            )}
        >
            {option.icon}
            <div className="text-left">
                <div>{option.label}</div>
                <div className="text-[10px] opacity-70">
                    {option.description}
                </div>
            </div>
        </button>
    )
}

