"use client"

import React, { useCallback, useState } from "react"
import { AdminMpegDashTestHeader } from "./Header"
import { ConfigCard } from "./ConfigCard"
import { PreviewCard } from "./PreviewCard"
import { QuickTestUrls } from "./QuickTestUrls"
import type { QuickTestUrl } from "@/modules/types/admin-mpeg-dash-test"
import { VideoRendererType } from "@/modules/types/enums/video-renderer-type"
import { Box } from "@/components/frames/Box"

/**
 * Admin tool page for testing the VideoRenderer with all 3 renderer types.
 * Owns the URL + active-type state and action handlers; renders presentational cards.
 * Enter a URL and pick Standard / MpegDash / Youtube to preview.
 */
export const AdminMpegDashTestPage = () => {
    const [url, setUrl] = useState("")
    const [activeType, setActiveType] = useState<VideoRendererType>(
        VideoRendererType.MpegDash,
    )

    const onChangeUrl = useCallback(
        (value: string) => setUrl(value),
        [],
    )

    const onSelectType = useCallback(
        (type: VideoRendererType) => setActiveType(type),
        [],
    )

    /** Load a preset: set both its URL and renderer type. */
    const onSelectQuickTestUrl = useCallback(
        (item: QuickTestUrl) => {
            setUrl(item.url)
            setActiveType(item.type)
        },
        [],
    )

    return (
        <div className={"min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 p-4 @app-md:p-8"}>
            <Box principle="center-measure" className="mx-auto max-w-4xl space-y-6"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <AdminMpegDashTestHeader />

                <ConfigCard
                    url={url}
                    activeType={activeType}
                    onChangeUrl={onChangeUrl}
                    onSelectType={onSelectType}
                />

                <PreviewCard
                    url={url}
                    activeType={activeType}
                />

                <QuickTestUrls onSelect={onSelectQuickTestUrl} />
            </Box>
        </div>
    )
}

"use client"

import React, { useCallback, useState } from "react"
import { StackV } from "@/components/frames/Stack"
import {
    Button,
    Card,
    CardContent,
    TextArea,
    TextField,
} from "@heroui/react"
import { useTranslations } from "next-intl"
import { CommunityChannel } from "@/modules/api/graphql/queries/types/community-feed"
import { useMutateCreateCommunityPostSwr } from "@/hooks/swr/api/graphql/mutations/useMutateCreateCommunityPostSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for the {@link CommunityComposer} sub-component. */
export interface CommunityComposerProps {
    /** Channel new posts are published to (the "all" tab posts to General). */
    channel: CommunityChannel
    /** Called after a post is created so the feature can refetch the feed. */
    onPosted: () => void
}

/**
 * Compose box for a new community post: a body textarea + a post button. Creation
 * goes through the toast-wrapped mutation, so the server-side quota error (for
 * non-members over their limit) surfaces as a toast automatically. On success the
 * box clears and `onPosted` refetches the feed.
 *
 * @param props - {@link CommunityComposerProps}
 */
export const CommunityComposer = ({
    channel,
    onPosted,
}: CommunityComposerProps) => {
    const t = useTranslations()
    const [body, setBody] = useState("")
    const runGraphQL = useGraphQLWithToast()
    const { trigger: createPost, isMutating } = useMutateCreateCommunityPostSwr()

    /** Validate, submit, then clear + refetch on success. */
    const onSubmit = useCallback(async () => {
        // ignore empty/whitespace-only bodies
        const trimmed = body.trim()
        if (!trimmed) {
            return
        }
        // create via the toast wrapper so quota/auth errors surface as a toast;
        // the action returns the inner GraphQLResponse the toast wrapper inspects
        const ok = await runGraphQL(
            async () => {
                const result = await createPost({
                    channel,
                    body: trimmed,
                })
                return result.data!.createCommunityPost
            },
            { showSuccessToast: true },
        )
        // only clear + refetch when the create actually succeeded
        if (ok) {
            setBody("")
            onPosted()
        }
    }, [body, channel, createPost, runGraphQL, onPosted])

    return (
        <Card>
            <CardContent>
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                    items={[
                        () => (
                            <TextField variant="secondary">
                                <TextArea
                                    rows={3}
                                    value={body}
                                    onChange={(event) => setBody(event.target.value)}
                                    placeholder={t("community.composerPlaceholder")}
                                    aria-label={t("community.composerPlaceholder")}
                                    className="resize-none"
                                />
                            </TextField>
                        ),
                        () => (
                            <div className="flex justify-end">
                                <Button
                                    variant="primary"
                                    isPending={isMutating}
                                    isDisabled={!body.trim()}
                                    onPress={() => void onSubmit()}
                                >
                                    {t("community.post")}
                                </Button>
                            </div>
                        ),
                    ]} />
            </CardContent>
        </Card>
    )
}

import React from "react"
import type { Key } from "react"
import { ChatCircleIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { TabsCard, type TabsCardItem } from "@/components/blocks/navigation/TabsCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CommunityComposer } from "./CommunityComposer"
import { CommunityPost } from "@/components/blocks/community/CommunityPost"
import { CommunityChannel } from "@/modules/api/graphql/queries/types/community-feed"
import type { QueryCommunityFeedItemData } from "@/modules/api/graphql/queries/types/community-feed"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** How many placeholder rows the co-located skeleton shows for the feed list. */
const SKELETON_ROW_COUNT = 3

/**
 * One placeholder feed row. `CommunityPost` (and the `CommunityPostCard` it wraps)
 * take a required `post` and carry no `isSkeleton` of their own, so this hand-mirrors
 * the card face right where it sits ΓÇö author row, body block, reaction footer ΓÇö
 * instead of pulling in a separate skeleton tree (loading-and-skeleton.md).
 */
const CommunityFeedSkeletonRow = () => (
    <SurfaceCard body={() => (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => (
                    <StackH gap={4} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={[
                            () => <Avatar isSkeleton size="md" />,
                            () => (
                                <StackV gap={3} principle="identity"
                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                    classNames={["min-w-0", "flex-1"]} items={[
                                        () => <Typography size="sm" isSkeleton />,
                                        () => <Typography size="xs" isSkeleton classNames={["w-3/4"]} />,
                                    ]} />
                            ),
                        ]} />
                ),
                () => <Skeleton className="h-16 w-full rounded-xl" />,
                () => (
                    <StackH gap={6} principle="block-boundary"
                        explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            () => <Skeleton className="h-7 w-24 rounded-full" />,
                            () => <Skeleton className="h-7 w-14 rounded-full" />,
                        ]} />
                ),
            ]} />
    )} />
)

/** All display text, already localized by the connected `CommunityFeedPage`; a story passes i18n keys. */
export interface CommunityFeedLabels {
    /** Page title. */
    title: string
    /** Page description under the title. */
    description: string
    /** Label on the "Chat" header action button. */
    chatLabel: string
    /** Accessible name for the channel tab strip. */
    channelTabsAriaLabel: string
    /** Error-branch title (feed failed to load). */
    errorTitle: string
    /** Retry button label, shared by the error branch. */
    retryLabel: string
    /** Empty-branch title when a channel filter has no posts. */
    emptyFilteredTitle: string
    /** Action label that clears the channel filter back to "all". */
    viewAllChannelsLabel: string
    /** Empty-branch title when the whole platform has no posts yet. */
    emptyTitle: string
    /** Action label that sends an empty-feed visitor into the course catalog. */
    browseCoursesLabel: string
    /** "Load more" button label under the feed. */
    loadMoreLabel: string
}

/** Props for {@link _CommunityFeedPage} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CommunityFeedPageProps {
    /** First load, nothing in hand ΓåÆ the feed region shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with a resolved page that carries zero posts ΓåÆ the empty branch. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error branch (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ΓÇö refetches the feed. Paired with `labels.retryLabel`. */
    onRetry?: () => void
    /** `true` while a channel filter is active ΓÇö picks which of the two empty messages shows. */
    isFilteredEmpty?: boolean
    /** Channel tab strip, already resolved (i18n'd labels). */
    channelTabs: Array<TabsCardItem>
    /** Currently selected channel tab key ("all" or a {@link CommunityChannel}). */
    selectedChannelKey: string
    /** Fired with the newly selected tab key. */
    onChannelChange: (key: Key) => void
    /** `true` (signed-in) ΓåÆ renders the composer above the feed. */
    showComposer: boolean
    /** Channel the composer posts to (the "all" tab defaults to General). */
    composerChannel: CommunityChannel
    /** Called after a post is created so the feature can refetch the feed. */
    onPosted: () => void
    /** Clears the active channel filter back to "all channels". */
    onViewAllChannels: () => void
    /** Sends a platform-empty visitor into the course catalog. */
    onBrowseCourses: () => void
    /** Opens the community chat route. */
    onChatClick: () => void
    /** The flattened, newest-first feed page. */
    items: Array<QueryCommunityFeedItemData>
    /** Whether the viewer is signed in ΓÇö gates reactions + the comment composer on each post. */
    authenticated: boolean
    /** React handler forwarded to each post ΓÇö reacts, then refetches. */
    onReact: (postId: string, type: ReactionType | null) => void
    /** Called when a post's thread changes (new comment) so the feed can refresh. */
    onChanged: () => void
    /** `true` iff the last loaded page still carries a next cursor. */
    hasMore: boolean
    /** `true` while a "load more" page is in flight. */
    isLoadingMore: boolean
    /** Requests the next page. */
    onLoadMore: () => void
    labels: CommunityFeedLabels
}

/**
 * Community feed page (Facebook/Twitter-style) ΓÇö the presentational half of
 * {@link CommunityFeedPage}, composed on the tier-correct vocabulary (`PageContainer` /
 * `PageHeader` / `TabsCard` / `SurfaceCard`). The header, channel tabs, and composer
 * always render; only the feed region itself runs the fixed order
 * error ΓåÆ loading ΓåÆ empty ΓåÆ content: `error` falls to the shared `AsyncContentError`
 * frame, `isEmpty` to `AsyncContentEmpty` (filtered vs platform-wide), and otherwise
 * the post list renders with `isSkeleton` threaded to every leaf that supports it so
 * the shimmer mirrors the loaded shape (loading-and-skeleton.md). See `tiers/split.md`
 * ΓÇö the connected `index.tsx` owns the fetch, the channel filter, and i18n.
 *
 * @param props - {@link CommunityFeedPageProps}
 */
export const _CommunityFeedPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    isFilteredEmpty = false,
    channelTabs,
    selectedChannelKey,
    onChannelChange,
    showComposer,
    composerChannel,
    onPosted,
    onViewAllChannels,
    onBrowseCourses,
    onChatClick,
    items,
    authenticated,
    onReact,
    onChanged,
    hasMore,
    isLoadingMore,
    onLoadMore,
    labels,
}: CommunityFeedPageProps) => {
    return (
        <PageContainer>
            <StackV gap={7} principle="layout-split"
                explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            title={labels.title}
                            description={labels.description}
                            actions={(
                                <Button
                                    variant="secondary"
                                    size="sm"
                                    prefixIcon={ChatCircleIcon}
                                    label={labels.chatLabel}
                                    onPress={onChatClick}
                                />
                            )}
                        />
                    ),
                    () => (
                        <StackV gap={6} principle="block-boundary"
                            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: channelTabs,
                                            selectedKey: selectedChannelKey,
                                            ariaLabel: labels.channelTabsAriaLabel,
                                            onSelectionChange: onChannelChange,
                                        }}
                                    />
                                ),
                                ...(showComposer ? [() => (
                                    <CommunityComposer channel={composerChannel} onPosted={onPosted} />
                                )] : []),
                                () => {
                                    // error beats a stale loading flag; empty only once settled
                                    if (error) {
                                        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retryLabel} />
                                    }
                                    if (!isSkeleton && isEmpty) {
                                        // empty feed is still a conversion surface. Two distinct reasons need
                                        // two distinct empties (┬ºState-matrix): filtered-empty offers a way
                                        // back to "all channels"; platform-empty invites into courses.
                                        return isFilteredEmpty ? (
                                            <AsyncContentEmpty
                                                title={labels.emptyFilteredTitle}
                                                action={() => (
                                                    <Button variant="secondary" size="sm" label={labels.viewAllChannelsLabel} onPress={onViewAllChannels} />
                                                )}
                                            />
                                        ) : (
                                            <AsyncContentEmpty
                                                title={labels.emptyTitle}
                                                action={() => (
                                                    <Button variant="secondary" size="sm" label={labels.browseCoursesLabel} onPress={onBrowseCourses} />
                                                )}
                                            />
                                        )
                                    }

                                    // ROWS ΓÇö while shimmering, placeholder rows keep the SAME count shape as the
                                    // real list; `CommunityPost` has no `isSkeleton` of its own (missingSkeletonSupport).
                                    const rowItems = isSkeleton
                                        ? Array.from({ length: SKELETON_ROW_COUNT }, () => () => <CommunityFeedSkeletonRow />)
                                        : items.map((post) => () => (
                                            <CommunityPost
                                                post={post}
                                                authenticated={authenticated}
                                                onReact={authenticated ? onReact : undefined}
                                                onChanged={onChanged}
                                            />
                                        ))

                                    return (
                                        <StackV gap={6} principle="block-boundary"
                                            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                                            items={[
                                                ...rowItems,
                                                ...(!isSkeleton && hasMore ? [() => (
                                                    <div className="flex justify-center">
                                                        <Button
                                                            variant="secondary"
                                                            size="sm"
                                                            isPending={isLoadingMore}
                                                            label={labels.loadMoreLabel}
                                                            onPress={onLoadMore}
                                                        />
                                                    </div>
                                                )] : []),
                                            ]} />
                                    )
                                },
                            ]} />
                    ),
                ]} />
        </PageContainer>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    Button,
    Card,
    CardContent,
    Chip,
    Spinner,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { useQueryMyInstallmentPlansSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyInstallmentPlansSwr"
import { useMutatePayNextInstallmentSwr } from "@/hooks/swr/api/graphql/mutations/useMutatePayNextInstallmentSwr"
import type { InstallmentPlanItem } from "@/modules/api/graphql/queries/types/my-installment-plans"
import { PaymentType } from "@/modules/types/enums/payment-type"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { submitCheckout } from "@/modules/payment/submit-checkout"
import { pathConfig } from "@/resources/path"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Format an integer VND amount as "1.275.000Γé½". */
const formatVnd = (amount: number): string => `${amount.toLocaleString("vi-VN")}Γé½`

/** Chip color per plan lifecycle status ΓÇö semantic only, never accent. */
const STATUS_COLOR: Record<string, "success" | "warning" | "danger" | "muted"> = {
    Active: "success",
    Overdue: "warning",
    Defaulted: "danger",
    Completed: "muted",
}

/**
 * "My installment plans" ΓÇö lists the viewer's non-completed installment
 * plans and lets them pay the current cycle.
 *
 * Two render shapes share one list (mirrors `Sessions` ΓÇö per-plan `Card` with a
 * row action, not a `SurfaceListCard` since each plan is its own bounded object):
 * `Fixed` (fixed monthly amount + `ProgressMeter` "paid N/M installments") and
 * `FlexiblePool` (outstanding balance + an editable amount, floor-clamped to
 * this cycle's minimum). Paying opens the gateway checkout via the shared
 * `payNextInstallment` mutation, then revalidates the list. Mounted by
 * `/profile/settings/installments`.
 */
export const InstallmentPlansPage = () => {
    const t = useTranslations()
    const router = useRouter()
    const {
        data: plans,
        isLoading,
        error,
        mutate,
    } = useQueryMyInstallmentPlansSwr()
    const { trigger: triggerPayNextInstallment } = useMutatePayNextInstallmentSwr()
    const runGraphQL = useGraphQLWithToast()

    // the plan id currently being paid (drives the per-row spinner)
    const [payingId, setPayingId] = useState<string | null>(null)
    // FlexiblePool custom amounts, keyed by plan id ΓÇö seeded lazily from minPaymentVnd
    const [customAmountByPlan, setCustomAmountByPlan] = useState<Record<string, number>>({})

    const planList = plans ?? []

    /** The amount to charge for a plan ΓÇö the edited FlexiblePool value, else the minimum. */
    const amountFor = useCallback(
        (plan: InstallmentPlanItem) => customAmountByPlan[plan.id] ?? plan.minPaymentVnd,
        [customAmountByPlan],
    )

    /** Clamp a FlexiblePool amount edit to never go below this cycle's minimum. */
    const onAmountChange = useCallback(
        (plan: InstallmentPlanItem, raw: string) => {
            const digits = Number(raw.replace(/\D/g, ""))
            const clamped = Math.max(digits || 0, plan.minPaymentVnd)
            setCustomAmountByPlan((prev) => ({ ...prev, [plan.id]: clamped }))
        },
        [],
    )

    /** Pay a plan's current cycle (PayOS ΓÇö the only gateway offered here), then refresh the list. */
    const onPay = useCallback(
        async (plan: InstallmentPlanItem) => {
            setPayingId(plan.id)
            try {
                let checkoutUrl = ""
                let checkoutFields: string | null | undefined
                const success = await runGraphQL(
                    async () => {
                        const amountVnd = plan.planType === "FlexiblePool" ? amountFor(plan) : undefined
                        const response = await triggerPayNextInstallment({
                            planId: plan.id,
                            paymentType: PaymentType.PayOS,
                            returnUrl: window.location.href,
                            cancelUrl: window.location.href,
                            amountVnd,
                        })
                        if (!response.data?.payNextInstallment) {
                            throw new Error(response.error?.message)
                        }
                        const data = response.data.payNextInstallment.data
                        checkoutUrl = data?.checkoutUrl ?? ""
                        checkoutFields = data?.checkoutFields
                        return response.data.payNextInstallment
                    },
                    {
                        showSuccessToast: false,
                        showErrorToast: true,
                    },
                )
                if (success && checkoutUrl) {
                    submitCheckout({ checkoutUrl, checkoutFields })
                }
            } finally {
                setPayingId(null)
            }
        },
        [runGraphQL, triggerPayNextInstallment, amountFor],
    )

    return (
        <StackV gap={7} principle="layout-split"
            explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("installmentPlans.title")} />}
                        title={t("installmentPlans.title")}
                        description={t("installmentPlans.subtitle")}
                    />
                ),

                () => (
                    <AsyncContent
                        isLoading={isLoading && !plans}
                        skeleton={(
                            <StackV gap={4} principle="content-row" explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." items={[0, 1].map((row) => () => (
                                <Skeleton key={row} className="h-40 w-full rounded-2xl" />
                            ))} />
                        )}
                        isEmpty={planList.length === 0}
                        emptyContent={{
                            title: t("installmentPlans.empty"),
                            description: t("installmentPlans.emptyDesc"),
                            onRetry: () => router.push(pathConfig().locale().course().build()),
                            retryLabel: t("installmentPlans.emptyCta"),
                        }}
                        error={error}
                        errorContent={{
                            title: t("installmentPlans.empty"),
                            onRetry: () => { void mutate() },
                        }}
                    >
                        <StackV gap={4} principle="content-row" explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." items={planList.map((plan) => () => {
                            const isFixed = plan.planType === "Fixed"
                            const isLocked = plan.status === "Defaulted"
                            const statusColor = STATUS_COLOR[plan.status] ?? "muted"
                            const isPaying = payingId === plan.id
                            return (
                                <Card key={plan.id}>
                                    <CardContent>
                                        <StackV gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={[
                                                () => (
                                                    <StackH gap={4} principle="content-row" justify="between" align="center"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <Chip
                                                                    size="sm"
                                                                    variant="soft"
                                                                    color={statusColor === "muted" ? "default" : statusColor}
                                                                >
                                                                    <Chip.Label>{t(`installmentPlans.status.${plan.status}`)}</Chip.Label>
                                                                </Chip>
                                                            ),
                                                            () => (
                                                                <Typography type="body-xs" color="muted">
                                                                    {isFixed
                                                                        ? t("installmentPlans.termMonths", { months: plan.months ?? 0 })
                                                                        : t("installmentPlans.flexiblePool")}
                                                                </Typography>
                                                            ),
                                                        ]} />
                                                ),

                                                () => (plan.courses.length > 0 ? (
                                                    <Cluster gap={3} principle="chip-row" explain="Lets chips share one wrapping row so related tags stay together without stacking as a column." items={plan.courses.map((course) => () => (
                                                        <Chip key={course.id} size="sm" variant="soft" color="default">
                                                            <Chip.Label>{course.title}</Chip.Label>
