                                                    ))} />
                                                ) : null),

                                                () => (isFixed ? (
                                                    <>
                                                        <StackH gap={4} principle="content-row" explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." justify="between" align="center" items={[() => (
                                                            <Typography type="body-sm" weight="semibold">
                                                                {formatVnd(plan.monthlyAmountVnd ?? 0)}
                                                                <Typography type="body-xs" color="muted" className="ml-1 inline">
                                                                    {t("installmentPlans.perCycle")}
                                                                </Typography>
                                                            </Typography>
                                                        )]} />
                                                        <ProgressMeter
                                                            value={plan.installmentsPaid ?? 0}
                                                            max={plan.months ?? 1}
                                                            label={t("installmentPlans.progress", {
                                                                paid: plan.installmentsPaid ?? 0,
                                                                months: plan.months ?? 0,
                                                            })}
                                                        />
                                                    </>
                                                ) : (
                                                    <>
                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                            items={[
                                                                () => (
                                                                    <Typography type="body-sm" color="muted">
                                                                        {t("installmentPlans.remaining")}
                                                                    </Typography>
                                                                ),
                                                                () => (
                                                                    <Typography type="body-sm" weight="semibold">
                                                                        {formatVnd(plan.remainingVnd ?? 0)}
                                                                    </Typography>
                                                                ),
                                                            ]} />
                                                        <Typography type="body-xs" color="muted">
                                                            {t("installmentPlans.minPaymentFormula", {
                                                                percent: plan.minPaymentPercent ?? 0,
                                                                floor: formatVnd(plan.minPaymentFloorVnd ?? 0),
                                                            })}
                                                        </Typography>
                                                        <StackH gap={3} principle="identity" align="center"
                                                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                            items={[
                                                                () => (
                                                                    <TextField
                                                                        className="max-w-[160px]"
                                                                        value={amountFor(plan).toLocaleString("vi-VN")}
                                                                        onChange={(value) => onAmountChange(plan, value)}
                                                                        isDisabled={isPaying}
                                                                        aria-label={t("installmentPlans.amountLabel")}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Typography type="body-xs" color="muted">
                                                                        {t("installmentPlans.minLabel", { amount: formatVnd(plan.minPaymentVnd) })}
                                                                    </Typography>
                                                                ),
                                                            ]} />
                                                    </>
                                                )),

                                                () => (isLocked ? (
                                                    <Callout
                                                        status="danger"
                                                        title={t("installmentPlans.lockedTitle")}
                                                        description={t("installmentPlans.lockedDesc")}
                                                    />
                                                ) : null),

                                                () => (
                                                    <StackH gap={4} principle="content-row" justify="between" align="center"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        items={[
                                                            () => (
                                                                <Typography type="body-xs" color="muted">
                                                                    {plan.nextDueAt
                                                                        ? t("installmentPlans.nextDue", { date: new Date(plan.nextDueAt).toLocaleDateString("vi-VN") })
                                                                        : ""}
                                                                </Typography>
                                                            ),
                                                            () => (
                                                                <Button
                                                                    variant={isLocked ? "danger" : "primary"}
                                                                    size="sm"
                                                                    isDisabled={isPaying}
                                                                    onPress={() => { void onPay(plan) }}
                                                                >
                                                                    {isPaying ? (
                                                                        <Spinner size="sm" color="current" />
                                                                    ) : isLocked ? (
                                                                        t("installmentPlans.unlock")
                                                                    ) : isFixed ? (
                                                                        t("installmentPlans.payThisCycle")
                                                                    ) : (
                                                                        t("installmentPlans.pay")
                                                                    )}
                                                                </Button>
                                                            ),
                                                        ]} />
                                                ),
                                            ]} />
                                    </CardContent>
                                </Card>
                            )
                        })} />
                    </AsyncContent>
                ),
            ]} />
    )
}

import React from "react"
import { MapTrifoldIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@/components/blocks/learn/MindMapRail"
import { MindMapContinueButton } from "@/components/blocks/learn/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@/components/blocks/learn/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@/components/composites/stats/Legend"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { type ComponentTypeWithSkeleton, type SkeletonProps } from "@/components/frames/_slot"
import { ResizableRail } from "@/components/behaviors/ResizableRail"
import { StackH, StackV } from "@/components/frames/Stack"
import { Stage } from "@/components/frames/Stage"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { FillAvailable } from "@/components/frames/FillAvailable"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * SCREEN ΓÇö `_MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list and the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose).
 *
 * The graph engine arrives as the `canvas` slot. This screen lays out the rail,
 * the floating chrome and the empty state; it does not know ReactFlow exists.
 *
 * FIVE LEAVES, by STRUCTURE ΓÇö `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 *
 * PRESENTATIONAL ΓÇö every input arrives as a prop; the connected `index.tsx`
 * owns the fetch, the rail's filter state, and every `t()` call (`split.md`).
 *
 * Emits its own identity (`data-tier="page"` / `data-component="MindMapPage"`)
 * unconditionally on its root, same as `_ModulePage`/`_ContentPage` ΓÇö see
 * `split.md`'s "Identity is data-tier + data-component" section.
 *
 * The viewport-relative full-bleed height, the canvas's floating-chrome
 * anchoring, and the rail's scroll region are all composed on `Stage` /
 * `ScrollArea` (`@/components/frames/Stage`, `@/components/frames/ScrollArea`)
 * ΓÇö the two frames the vocabulary gap this screen flagged in a previous pass
 * was built to close. No raw `className` shape remains on this page.
 */

/** Which shape of the mind map this screen renders ΓÇö see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render ΓÇö see the file header for how the two differ. */
    variant: MindMapVariant

    // ΓöÇΓöÇ `workspace`: the `MindMapRail` search pane ΓöÇΓöÇ
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` ΓåÆ the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ΓöÇΓöÇ `standalone`: floating chrome over the canvas ΓöÇΓöÇ
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` ΓåÆ the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries ΓÇö colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` ΓåÆ canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ΓöÇΓöÇ shared ΓöÇΓöÇ
    /** `true` ΓåÆ every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` ΓåÆ the course has no authored map/modules yet. `workspace`-ONLY ΓÇö see the file header. */
    isEmpty?: boolean

    /**
     * The graph itself, mounted by the caller. A screen composes; it does not own a
     * rendering engine ΓÇö and an earlier pass left a literal placeholder here instead
     * of a slot, which meant wiring this screen would have shipped a mind-map page
     * with no map in it.
     */
    canvas: ComponentTypeWithSkeleton
    /**
     * The empty state's one way forward ΓÇö browse the course's modules instead.
     * Omit ΓåÆ the empty state states the fact and offers nothing, which is right
     * only when there is nowhere useful to send the reader.
     */
    onBrowseModules?: () => void
    /** Every word the whole-screen empty state says ΓÇö resolved by the connected half. */
    labels: MindMapPageLabels
}

/** All display text this screen owns, already localized by the connected half. */
export interface MindMapPageLabels {
    /** Heading when the course has no authored map yet. */
    emptyTitle: string
    /** Body when the course has no authored map yet. */
    emptyDescription: string
    /** Label on the empty state's way forward, paired with {@link MindMapPageProps.onBrowseModules}. */
    emptyCta: string
}

/** localStorage key + bounds the real workspace persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

/** This screen's own identity ΓÇö handed down to whichever `Stage` is the root, per branch, instead of a wrapping div (BLOCK-2). See `_identity.ts`. */
const MIND_MAP_PAGE_IDENTITY: CallerIdentity = { tier: "page", component: "MindMapPage" }

/**
 * `workspace` empty state ΓÇö the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case. The
 * viewport-relative full-bleed height is `Stage`'s `fill="viewport"` ΓÇö the
 * same shape the real spine below uses for the same reason.
 */
const MindMapWorkspaceEmpty = ({ labels, onBrowseModules }: MindMapWorkspaceEmptyProps) => (
    <Stage
        fill="viewport"
        identity={MIND_MAP_PAGE_IDENTITY}
        canvas={() => (
            <StackV
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={[() => (
                    <AsyncContentEmpty

                        icon={MapTrifoldIcon}
                        title={labels.emptyTitle}
                        description={labels.emptyDescription}
                        onRetry={onBrowseModules}
                        retryLabel={labels.emptyCta}
                    />
                )]}
            />
        )}
    />
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const _MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
    canvas: Canvas,
    onBrowseModules,
    labels,
}: MindMapPageProps) => {
    // Built as a thunk, called only for the non-empty branch below ΓÇö mirrors
    // `_ModulePage`'s `spine(isSkeleton)`, so the empty branch never pays for
    // building a tree it will not render.
    const workspace = () => {
        const railSection = (
            <MindMapRail

                query={query}
                onQuery={onQuery}
                tier={tier}
                onTier={onTier}
                items={items}
                selectedId={selectedId}
                onPick={onPick}
                isLoading={isRailLoading}
                ariaLabel={railAriaLabel}
                tierAriaLabel={railTierAriaLabel}
                isSkeleton={isSkeleton}

            />
        )

        // The canvas region's floating chrome ΓÇö in the real app these render as the
        // SAME ReactFlow engine's own Panel children. Only present (`standalone`,
        // resting) ΓÇö `Stage` skips a slot entirely when it is `undefined`.
        const showOverlays = variant === "standalone" && !isSkeleton

        const topCenterSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapContinueButton

                            resumeHref={resumeHref}
                            allContentDone={allContentDone}
                            onResume={onResume}
                            continueAriaLabel={continueAriaLabel}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        const bottomStartSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => <Legend items={legendItems} />]}
                />
            )
            : undefined

        const bottomEndSlot = showOverlays
            ? ({ isSkeleton }: SkeletonProps) => (
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapFullscreenButton

                            onZoomIn={onZoomIn}
                            onZoomOut={onZoomOut}
                            onToggleFullscreen={onToggleFullscreen}
                            isFullscreen={isFullscreen}
                            ariaLabels={fullscreenAriaLabels}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            )
            : undefined

        // The canvas region: the out-of-reach engine's gap, plus (standalone only) the
        // floating chrome that in the real app renders as the SAME engine's own Panel
        // children. `Stage` owns the positioning context and the three floating anchors ΓÇö
        // no page-level `relative`/`absolute` left.
        const canvasStage = (
            <FillAvailable
                at="base"
                explain="Canvas stage consumes remaining workspace width beside the resizable rail ΓÇö not a fixed-size peer."
                body={() => (
                    <Stage
                        canvas={Canvas}
                        topCenter={topCenterSlot}
                        bottomStart={bottomStartSlot}
                        bottomEnd={bottomEndSlot}
                        isSkeleton={isSkeleton}
                    />
                )}
            />
        )

        const workspaceRail = (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={railResizeAriaLabel}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <ScrollArea
                    axis="y"
                    isSkeleton={isSkeleton}
                    body={({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            principle="page-pad"
                            explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface."
                            isSkeleton={isSkeleton}
                            items={[() => railSection]}
                        />
                    )}
                />
            </ResizableRail>
        )

        const workspaceSections = (
            <>
                {variant === "workspace" ? workspaceRail : null}
                {canvasStage}
            </>
        )

        // The viewport-relative full-bleed height ΓÇö the shell's own chrome height
        // subtracted ΓÇö is `Stage`'s `fill="viewport"`; the rail + canvas row is its
        // `canvas` slot (a stage need not be a literal drawing surface ΓÇö see the
        // frame's own file header for why this is the shape it names).
        return (
            <Stage
                fill="viewport"
                isSkeleton={isSkeleton}
                identity={MIND_MAP_PAGE_IDENTITY}
                canvas={({ isSkeleton }: SkeletonProps) => (
                    <StackH gap={1} isSkeleton={isSkeleton} items={[() => workspaceSections]} />
                )}
            />
        )
    }

    return variant === "workspace" && isEmpty
        ? <MindMapWorkspaceEmpty labels={labels} onBrowseModules={onBrowseModules} />
        : workspace()
}

export { _MindMapPage }

type MindMapWorkspaceEmptyProps = {
    labels: MindMapPageLabels
    onBrowseModules?: () => void
}

"use client"

import React, { useCallback, useMemo, useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCourseMindMapSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseMindMapSwr"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import type { CourseMindMapNodeData } from "@/modules/api/graphql/queries/types"
import { tierAllows } from "@/modules/utils/mind-map"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { ConceptMap } from "@/components/blocks/learn/ConceptMap"
import { MindMapCanvas } from "@/components/blocks/learn/ConceptMap/MindMapCanvas"
import type {
    MindMapPopularity,
    MindMapRailItem,
    MindMapRailTier,
} from "@/components/blocks/learn/MindMapRail"
import { Stage } from "@/components/frames/Stage"
import { _MindMapPage, type MindMapVariant } from "./component"

/**
 * The graph carries popularity as a free-form string; the rail names a closed set.
 * Anything else (or nothing) reads as "no tier", which is what structural nodes are.
 */
const toPopularity = (value: string | null | undefined): MindMapPopularity =>
    value === "high" || value === "medium" || value === "low" ? value : null

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /**
     * Which shape to render. `workspace` is the learn-shell third column (rail
     * beside the graph); `standalone` is the full-bleed map with floating chrome.
     */
    variant?: MindMapVariant
}

/**
 * `MindMapPage` ΓÇö the CONNECTED half of the course keyword graph. Owns the
 * course fetch (a hard refresh straight into this route has no other loader, so
 * the graph would otherwise stay empty), the map fetch, and the search + tier +
 * selection state that drives BOTH panes: the rail lists the matching keywords,
 * the canvas hides the non-matches. Selecting a keyword ΓÇö from a canvas node OR
 * a rail row ΓÇö recentres the map on it and opens its drawer.
 *
 * The filter is a plain in-memory pass over the loaded tree, not a query: the
 * whole graph is already in hand, so typing has to feel instant.
 *
 * @param props - {@link MindMapPageProps}
 */
export const MindMapPage = ({ variant = "workspace" }: MindMapPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const course = useAppSelector((state) => state.course.entity)
    const displayId = useAppSelector((state) => state.course.displayId)
    const { isLoading: isCourseLoading, error: courseError, mutate: reloadCourse } = useQueryCourseSwr()
    const { data, isLoading: isMapLoading } = useQueryCourseMindMapSwr(displayId ?? null)

    const [query, setQuery] = useState("")
    const [tier, setTier] = useState<MindMapRailTier>("all")
    const [selectedId, setSelectedId] = useState<string | null>(null)

    // The rail's result list: concept keywords clearing the tier floor and (while
    // typing) the substring, each carrying its ancestor breadcrumb for context.
    const items = useMemo<Array<MindMapRailItem>>(
        () => {
            if (!data) {
                return []
            }
            const value = query.trim().toLowerCase()
            const nodeById = new Map(data.nodes.map((node) => [node.id, node]))
            const parentOf = new Map(data.edges.map((edge) => [edge.target, edge.source]))
            const labelOf = (id: string) =>
                String((nodeById.get(id)?.data as unknown as CourseMindMapNodeData | undefined)?.label ?? "")
            const breadcrumb = (id: string) => {
                const parts: Array<string> = []
                let cursor = parentOf.get(id)
                while (cursor) {
                    const ancestor = nodeById.get(cursor)
                    if (!ancestor || ancestor.type === "course") {
                        break
                    }
                    parts.unshift(labelOf(cursor))
                    cursor = parentOf.get(cursor)
                }
                return parts.join(" ΓÇ║ ")
            }
            return data.nodes
                .filter((node) => {
                    if (node.type !== "concept") {
                        return false
                    }
                    const nodeData = node.data as unknown as CourseMindMapNodeData
                    return tierAllows(nodeData.popularity, tier)
                        && (!value || String(nodeData.label).toLowerCase().includes(value))
                })
                .map((node) => {
                    const nodeData = node.data as unknown as CourseMindMapNodeData
                    return {
                        id: node.id,
                        label: String(nodeData.label),
                        popularity: toPopularity(nodeData.popularity),
                        breadcrumb: breadcrumb(node.id),
                    }
                })
        },
        [data, query, tier],
    )

    const onPick = useCallback((id: string) => setSelectedId(id), [])

    /** The empty state's funnel: an unauthored map still has modules worth reading. */
    const onBrowseModules = useCallback(
        () => {
            if (!displayId) {
                return
            }
            router.push(pathConfig().locale(locale).course(displayId).learn().content().build())
        },
        [displayId, locale, router],
    )

    // The graph itself ΓÇö the screen mounts it, and knows nothing about it beyond
    // "something fills the canvas".
    const Canvas = useCallback(
        () => {
            // `standalone` draws the MODULE graph (progress + floating chrome); `workspace`
            // draws the KEYWORD graph beside the rail. Two different maps, one slot.
            if (variant === "standalone") {
                return <MindMapCanvas />
            }
            return data
                ? (
                    <ConceptMap
                        data={data}
                        query={query}
                        tier={tier}
                        selectedId={selectedId}
                        onSelectId={setSelectedId}
                    />
                )
                : null
        },
        [data, query, selectedId, tier, variant],
    )

    // error beats a stale loading flag (BLOCK-8); the course fetch is the one that
    // can fail loudly here, so it replaces the whole viewport rather than leaving
    // an empty canvas the reader would read as "this course has no map".
    if (courseError && !course) {
        return (
            <Stage
                identity={{ tier: "page", component: "MindMapPage" }}
                fill="viewport"
                canvas={() => (
                    <AsyncContentError
                        title={t("courseLanding.errorTitle")}
                        onRetry={() => { void reloadCourse() }}
                        retryLabel={t("courseLanding.retry")}
                    />
                )}
            />
        )
    }

    const isSkeleton = (isCourseLoading && !course) || (isMapLoading && !data)

    return (
        <_MindMapPage
            variant={variant}
            query={query}
            onQuery={setQuery}
            tier={tier}
            onTier={setTier}
            items={items}
            selectedId={selectedId ?? undefined}
            onPick={onPick}
            railAriaLabel={t("mindMap.toolbar.searchAria")}
            railTierAriaLabel={t("mindMap.toolbar.tierAria")}
            railResizeAriaLabel={t("mindMap.rail.resizeAria")}
            canvas={Canvas}
            isSkeleton={isSkeleton}
            // settled with a map that has no nodes ΓåÆ the course has nothing authored yet
            isEmpty={!isMapLoading && (!data || data.nodes.length === 0)}
            onBrowseModules={displayId ? onBrowseModules : undefined}
            labels={{
                emptyTitle: t("mindMap.emptyTitle"),
                emptyDescription: t("mindMap.emptyDescription"),
                emptyCta: t("mindMap.emptyCta"),
            }}
        />
    )
}

"use client"

import React, { useCallback, useEffect, useState } from "react"
import {
    Button,
    Label,
    Spinner,
    Switch,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setUser } from "@/redux/slices/user"
import { useMutateUpdateProfileSwr } from "@/hooks/swr/api/graphql/mutations/useMutateUpdateProfileSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { StackH, StackV } from "@/components/frames/Stack"
import type { SectionVisibility } from "@/modules/types/entities/user"

/**
 * The four gateable profile sections + their reused tab labels (Overview + CV are
 * never gated here). Each row toggles `sectionVisibility.<key>`; the label reuses
 * the existing `publicProfile.tabs.*` keys so it always matches the tab it hides.
 */
const SECTION_VISIBILITY_OPTIONS = [
    { key: "projects", labelKey: "publicProfile.tabs.projects", descKey: "profileEdit.sectionVisibilityDesc.projects" },
    { key: "challenges", labelKey: "publicProfile.tabs.challenges", descKey: "profileEdit.sectionVisibilityDesc.challenges" },
    { key: "skills", labelKey: "publicProfile.tabs.skills", descKey: "profileEdit.sectionVisibilityDesc.skills" },
    { key: "activity", labelKey: "publicProfile.tabs.activity", descKey: "profileEdit.sectionVisibilityDesc.activity" },
] as const

/** Seed the per-section visibility from the redux user (absent flags default to visible). */
const seedSectionVisibility = (
    visibility: SectionVisibility | undefined,
): SectionVisibility => ({
    projects: visibility?.projects ?? true,
    challenges: visibility?.challenges ?? true,
    skills: visibility?.skills ?? true,
    activity: visibility?.activity ?? true,
})

/**
 * Privacy settings feature container.
 *
 * The profile-VISIBILITY controls ΓÇö "Lock profile" (lock) + the per-section
 * "Profile visibility" group ΓÇö moved out of the edit-profile form into their own
 * settings page. Owns a small local form state seeded from the redux user; on save
 * it persists ONLY `{ profileLocked, sectionVisibility }` via `updateProfile` and
 * pushes the fresh user into redux. Mounted by `/profile/settings/privacy`.
 */
export const PrivacySettingsPage = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const user = useAppSelector((state) => state.user.user)

    const runGraphQL = useGraphQLWithToast()
    const updateProfileSwr = useMutateUpdateProfileSwr()

    // small local form state (this page only touches two fields, no RHF needed)
    const [profileLocked, setProfileLocked] = useState<boolean>(user?.profileLocked ?? false)
    const [sectionVisibility, setSectionVisibility] = useState<SectionVisibility>(
        seedSectionVisibility(user?.sectionVisibility),
    )
    const [isSubmitting, setIsSubmitting] = useState(false)

    // re-seed when the redux user changes (mirrors RHF `values` reinit)
    useEffect(() => {
        if (!user) {
            return
        }
        setProfileLocked(user.profileLocked ?? false)
        setSectionVisibility(seedSectionVisibility(user.sectionVisibility))
    }, [user])

    /** Persist ONLY the visibility fields, then push the fresh user into redux. */
    const onSubmit = useCallback(async () => {
        setIsSubmitting(true)
        await runGraphQL(
            async () => {
                const result = await updateProfileSwr.trigger({
                    profileLocked,
                    sectionVisibility,
                })
                const env = result?.data?.updateProfile
                if (!env) {
                    throw new Error(t("profileEdit.error"))
                }
                if (env.success && env.data) {
                    dispatch(setUser(env.data))
                }
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            },
        )
        setIsSubmitting(false)
    }, [runGraphQL, updateProfileSwr, profileLocked, sectionVisibility, dispatch, t])

    // signed-out guard
    if (!user) {
        return (
            <div className="flex flex-col items-center py-12">
                <StackV
                    gap={3}
                    align="center"
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                    items={[
                        () => (
                            <Typography type="h5" weight="semibold" align="center">
                                {t("profile.signedOut.title")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" align="center">
                                {t("profile.signedOut.desc")}
                            </Typography>
                        ),
                    ]}
                />
            </div>
        )
    }

    const lockRow = () => (
        <div className="my-2">
            <StackH
                gap={4}
                align="start"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <div className="flex flex-col gap-0">
                            <Label htmlFor="profile-locked">{t("profileEdit.lockProfile")}</Label>
                            <Typography type="body-xs" color="muted">
                                {t("profileEdit.lockProfileHint")}
                            </Typography>
                        </div>
                    ),
                    () => (
                        <Switch
                            className="shrink-0"
                            isSelected={profileLocked}
                            onChange={(selected) => setProfileLocked(selected)}
                            aria-label={t("profileEdit.lockProfile")}
                        >
                            <Switch.Content>
                                <Switch.Control>
                                    <Switch.Thumb />
                                </Switch.Control>
                            </Switch.Content>
                        </Switch>
                    ),
                ]}
            />
        </div>
    )

    const sectionRows = SECTION_VISIBILITY_OPTIONS.map((option) => () => (
        <div key={option.key} className="my-2">
            <StackH
                gap={4}
                align="start"
                justify="between"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <div className="flex min-w-0 flex-col gap-0">
                            <Label htmlFor={`profile-section-${option.key}`}>
                                {t(option.labelKey)}
                            </Label>
                            <Typography type="body-xs" color="muted">
                                {t(option.descKey)}
                            </Typography>
                        </div>
                    ),
                    () => (
                        <Switch
                            className="shrink-0"
                            isSelected={sectionVisibility[option.key]}
                            isDisabled={profileLocked}
                            onChange={(selected) => setSectionVisibility((prev) => ({
                                ...prev,
                                [option.key]: selected,
                            }))}
                            aria-label={t(option.labelKey)}
                        >
                            <Switch.Content>
                                <Switch.Control>
                                    <Switch.Thumb />
                                </Switch.Control>
                            </Switch.Content>
                        </Switch>
                    ),
                ]}
            />
        </div>
    ))

    const sectionGroupItems = [
        () => (
            <div className="flex flex-col gap-0">
                <Label htmlFor="profile-section-visibility">
                    {t("profileEdit.sectionVisibility")}
                </Label>
                <Typography type="body-xs" color="muted">
                    {profileLocked
                        ? t("profileEdit.sectionVisibilityLockedHint")
                        : t("profileEdit.sectionVisibilityHint")}
                </Typography>
            </div>
        ),
        () => (
            <div
                id="profile-section-visibility"
                className={profileLocked ? "pointer-events-none opacity-50" : undefined}
            >
                <StackV gap={4} items={sectionRows} />
            </div>
        ),
    ]

    const formItems = [
        lockRow,
        () => (
            <div aria-disabled={profileLocked}>
                <StackV gap={6} items={sectionGroupItems} />
            </div>
        ),
        () => (
            <Button
                variant="primary"
                size="lg"
                className="h-12 self-end text-base"
                isDisabled={isSubmitting}
                isPending={isSubmitting}
                onPress={() => onSubmit()}
            >
                {({ isPending }) => (
                    <>
                        {isPending ? (
                            <Spinner
                                color="current"
                                size="sm"
                            />
                        ) : null}
                        {t("profileEdit.save")}
                    </>
                )}
            </Button>
        ),
    ]

    return (
        <StackV gap={7} principle="layout-split"
            explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
            items={[
                () => (
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("profileSettings.privacy.title")} />}
                        title={t("profileSettings.privacy.title")}
                        description={t("profileSettings.privacy.description")}
                    />
                ),
                () => <StackV gap={6} items={formItems} />,
            ]} />
    )
}

"use client"

import React, {
    useMemo,
    useState,
} from "react"
import {
    Badge,
    Button,
    Label,
    Popover,
    Typography,
} from "@heroui/react"
import {
    FunnelIcon,
} from "@phosphor-icons/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useProfileUsername,
} from "@/hooks/profile/useProfileUsername"
import {
    CODING_DIFFICULTY_CHIP,
    domainLabel,
} from "@/modules/utils/coding-difficulty"
import { pathConfig } from "@/resources/path"
import { useQueryUserCodingHistorySwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingHistorySwr"
import { useQueryUserCodingProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingProgressSwr"
import { useQueryUserCodingRankSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingRankSwr"
import { useQueryUserCodingSkillsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserCodingSkillsSwr"
import { useQueryUserProfileSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserProfileSwr"
import { useQueryUserXpSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserXpSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { LanguageChip } from "@/components/blocks/chips/LanguageChip"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { SearchInput } from "@/components/blocks/form/SearchInput"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { TopicMasteryGrid } from "@/components/blocks/stats/TopicMasteryGrid"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** Solve-history rows shown before the "see more" link kicks in. */
const INITIAL_HISTORY = 6

/** Props for {@link ProfileCoding}. */
export type ProfileCodingProps = Record<string, never>
/**
 * CODING difficulty scale (easy/medium/hard ONLY ΓÇö coding problems, NOT the
 * challenge beginner/intermediate/advanced/insane taxonomy). 3-tone semantic
 * colours for the distribution bar: easy ΓåÆ green, medium ΓåÆ yellow, hard ΓåÆ red.
 */
const CODING_DIFFICULTY: ReadonlyArray<{ key: string; labelKey: string; color: string }> = [
    { key: "easy", labelKey: "publicProfile.skillsSnapshot.diffEasy", color: "var(--success)" },
    { key: "medium", labelKey: "publicProfile.skillsSnapshot.diffMedium", color: "var(--warning)" },
    { key: "hard", labelKey: "publicProfile.skillsSnapshot.diffHard", color: "var(--danger)" },
]

/** Single-select difficulty filter value ΓÇö `"all"` clears the filter. */
type DifficultyFilterValue = "all" | string
/** Single-select language filter value ΓÇö `"all"` clears the filter. */
type LanguageFilterValue = "all" | string

/**
 * Coding tab ("Skills & Coding") ΓÇö the profile owner's coding-practice proof
 * of work, built as a sibling of the Challenges tab: a headline metric row
 * (solved ┬╖ points ┬╖ acceptance ┬╖ rank ┬╖ top-percentile placeholder), a single
 * "Stats" {@link SurfaceCardList} that gathers the three breakdowns (by difficulty /
 * by topic / by language) under {@link Label} sub-headings, then a "Solve
 * history" {@link SurfaceCardList} whose rows mirror the Challenges submission style (title on top,
 * date on the left, difficulty/topic/language chips pushed right). Self-contained:
 * reads the username from the route, resolves it to the entity id, and drives its
 * own projection-backed SWR.
 *
 * @param props - optional className for the root element.
 */
export const ProfileCoding = () => {
    const t = useTranslations()
    const locale = useLocale()
    // route carries the username; resolve to the entity id the queries key off
    const username = useProfileUsername()
    const { data: user } = useQueryUserProfileSwr(username)
    const userId = user?.id ?? null
    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQueryUserCodingProgressSwr(userId)
    const historySwr = useQueryUserCodingHistorySwr(userId)
    const skillsSwr = useQueryUserCodingSkillsSwr(userId)
    // coding standing ΓÇö global rank + percentile by solved count (null when unranked)
    const standingSwr = useQueryUserCodingRankSwr(userId)
    // per-source XP breakdown ΓÇö codingXp is the coding-only XP (ledger sum),
    // NOT the global users.points balance the legacy "Code score" metric read
    const xpSwr = useQueryUserXpSwr(userId)
    const history = historySwr.data
    const skills = skillsSwr.data
    const standing = standingSwr.data
    const xp = xpSwr.data

    // null data (no coding activity yet) ΓåÆ treat every metric as zero
    const solved = data?.solvedProblemIds.length ?? 0

    // headline metric row (count ┬╖ XP ┬╖ top percentile ┬╖ rank), mirroring the Challenges tab.
    // percentile + rank hide when unranked (no solved problems).
    const stats: Array<{ key: string; value: string }> = [
        { key: "solved", value: String(solved) },
        { key: "xp", value: String(xp?.codingXp ?? 0) },
    ]
    if (standing?.percentile != null) {
        stats.push({ key: "percentile", value: `${standing.percentile}%` })
    }
    if (standing?.rank != null) {
        stats.push({ key: "rank", value: `#${standing.rank}` })
    }

    // breakdowns for the gathered "Stats" card
    const byLanguage = skills?.byLanguage ?? []
    const byDifficulty = skills?.byDifficulty ?? []
    const byDomain = skills?.byDomain ?? []
    const orderedDomain = [...byDomain].sort((a, b) => b.solved - a.solved)
    // difficulty distribution (easyΓåÆhard), coloured by the coding 3-tone scale
    const solvedByDifficulty = new Map(byDifficulty.map((item) => [item.key, item.solved]))
    const difficultySegments = CODING_DIFFICULTY
        .filter((difficulty) => (solvedByDifficulty.get(difficulty.key) ?? 0) > 0)
        .map((difficulty) => ({
            key: difficulty.key,
            label: t(difficulty.labelKey),
            value: solvedByDifficulty.get(difficulty.key) ?? 0,
            color: difficulty.color,
        }))
    const hasStats = difficultySegments.length > 0 || orderedDomain.length > 0 || byLanguage.length > 0

    const solvedHistory = history ?? []

    // search/filter toolbar (the "manage" layer) ΓÇö client-side, the list is
    // already small per-user; no server-side pagination needed here.
    const [search, setSearch] = useState("")
    const [difficultyFilter, setDifficultyFilter] = useState<DifficultyFilterValue>("all")
    const [languageFilter, setLanguageFilter] = useState<LanguageFilterValue>("all")
    // difficulty/language facets live behind a FUNNEL popover (same toolbar shape as
    // ProfileChallengeManage) ΓÇö the toolbar stays a single clean line regardless of how
    // many facet values exist; the funnel badges the active facet count.
    const [filterOpen, setFilterOpen] = useState(false)
    const activeFacetCount = (difficultyFilter !== "all" ? 1 : 0) + (languageFilter !== "all" ? 1 : 0)
    const clearFacets = () => {
        setDifficultyFilter("all")
        setLanguageFilter("all")
    }
    // filter option pools ΓÇö only difficulties/languages actually present in the history
    const difficultyOptions = useMemo(
        () => Array.from(new Set(solvedHistory.map((item) => item.difficulty).filter(Boolean))),
        [solvedHistory],
    )
    const languageOptions = useMemo(
        () => Array.from(new Set(solvedHistory.flatMap((item) => item.languages).filter(Boolean))),
        [solvedHistory],
    )
    const filteredHistory = useMemo(() => {
        const query = search.trim().toLowerCase()
        return solvedHistory.filter((item) => {
            if (query && !item.problemTitle.toLowerCase().includes(query)) {
                return false
            }
            if (difficultyFilter !== "all" && item.difficulty !== difficultyFilter) {
                return false
            }
            if (languageFilter !== "all" && !item.languages.includes(languageFilter)) {
                return false
            }
            return true
        })
    }, [solvedHistory, search, difficultyFilter, languageFilter])

    // cap the history; the rest hides behind a "see more" link
    const [showAllHistory, setShowAllHistory] = useState(false)
    const visibleHistory = showAllHistory ? filteredHistory : filteredHistory.slice(0, INITIAL_HISTORY)
    const hiddenHistory = filteredHistory.length - INITIAL_HISTORY
    // 2026-07-12: history/skills/standing/xp fire alongside `progress` but were
    // not part of this gate ΓÇö once `progress` resolved, the tab's sub-sections
    // (metric row's rank/percentile, the stats card, solve history) popped in
    // individually as each of those queries finished. Wait on all of them so the
    // one skeleton below covers the whole chain instead of only the first hop.
    const isFirstLoad = (!data && (isLoading || !userId))
        || (historySwr.isLoading && !history)
        || (skillsSwr.isLoading && !skills)
        || (standingSwr.isLoading && !standing)
        || (xpSwr.isLoading && !xp)

    const rootClassNames: Array<AllowedClassName> = []

    return (
        <AsyncContent
            isLoading={isFirstLoad}
            skeleton={(
                <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => <Skeleton className="h-20 w-full rounded-2xl" />,
                            ]} />
                        ),
                        () => (
                            <SurfaceCardList
                                label={t("publicProfile.coding.statsHeading")}
                                isSkeleton
                                items={[
                                    {
                                        key: "difficulty",
                                        content: () => <Skeleton.SegmentBar legendItems={3} />,
                                    },
                                    {
                                        key: "domain",
                                        content: () => (
                                            <Cluster gap={3} principle="chip-row"
                                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                items={
                                                    [0, 1, 2, 3, 4, 5, 6, 7].map((chip) => (
                                                        () => <Skeleton key={chip} className="h-7 w-20 rounded-full" />
                                                    ))
                                                } />
                                        ),
                                    },
                                    {
                                        key: "language",
                                        content: () => <Skeleton.SegmentBar legendItems={3} />,
                                    },
                                ]}
                            />
                        ),
                        () => (
                            <StackV gap={4} items={[
                                () => <Skeleton.Typography type="body-sm" width="1/4" />,
                                () => (
                                    <Cluster gap={4} principle="content-row" justify="between"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (
                                                <StackH gap={4} principle="content-row" classNames={["min-w-0", "flex-1"]}
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Skeleton className="h-9 min-w-0 flex-1 rounded-medium" />,
                                                        () => <Skeleton className="size-9 shrink-0 rounded-full" />,
                                                    ]} />
                                            ),
                                            () => <Skeleton.Typography type="body-sm" className="w-16 shrink-0" />,
                                        ]} />
                                ),
                                () => (
                                    <SurfaceCardList
                                        isSkeleton
                                        items={[0, 1, 2].map((row) => ({
                                            key: `history-skel-${row}`,
                                            content: () => (
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton.Chip />,
                                                        () => <Skeleton.Chip />,
                                                    ]} />
                                            ),
                                        }))}
                                    />
                                ),
                            ]} />
                        ),
                    ]} />
            )}
            isEmpty={solved === 0 && !hasStats && solvedHistory.length === 0}
            emptyContent={{
                title: t("publicProfile.coding.empty"),
                description: t("publicProfile.coding.emptyHint"),
            }}
            error={error}
            errorContent={{
                title: t("publicProfile.loadError"),
                onRetry: () => { void mutate() },
                retryLabel: t("publicProfile.loadErrorRetry"),
            }}
        >
            <StackV gap={6} principle="block-boundary" classNames={rootClassNames}
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <LabeledCard label={t("publicProfile.coding.metricsHeading")} frameless>
                            <StatRibbon
                                items={stats.map((stat) => ({
                                    key: stat.key,
                                    value: stat.value,
                                    label: t(`publicProfile.coding.metric.${stat.key}`),
                                }))}
                            />
                        </LabeledCard>
                    ),
                    ...(hasStats
                        ? [() => {
                            const statsItems: Array<SurfaceCardListItem> = [
                                ...(difficultySegments.length > 0
                                    ? [{
                                        key: "difficulty",
                                        content: () => (
                                            <StackV gap={3} principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Label>{t("publicProfile.coding.byDifficulty")}</Label>,
                                                    () => (
                                                        <SegmentBar
                                                            ariaLabel={t("publicProfile.coding.byDifficulty")}
                                                            segments={difficultySegments}
                                                        />
                                                    ),
                                                ]} />
                                        ),
                                    } satisfies SurfaceCardListItem]
                                    : []),
                                ...(orderedDomain.length > 0
                                    ? [{
                                        key: "domain",
                                        content: () => (
                                            <StackV gap={3} principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Label>{t("publicProfile.coding.byDomain")}</Label>,
                                                    () => (
                                                        <TopicMasteryGrid
                                                            ariaLabel={t("publicProfile.coding.byDomain")}
                                                            topics={orderedDomain.map((item) => ({
                                                                key: item.key,
                                                                label: domainLabel(item.key),
                                                                solved: item.solved,
                                                            }))}
                                                        />
                                                    ),
                                                ]} />
                                        ),
                                    } satisfies SurfaceCardListItem]
                                    : []),
                                ...(byLanguage.length > 0
                                    ? [{
                                        key: "language",
                                        content: () => (
                                            <StackV gap={3} principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Label>{t("publicProfile.coding.byLanguage")}</Label>,
                                                    () => (
                                                        <SegmentBar
                                                            ariaLabel={t("publicProfile.coding.byLanguage")}
                                                            segments={byLanguage.map((item) => ({
                                                                key: item.key,
                                                                label: getLanguageLabel(item.key),
                                                                value: item.solved,
                                                                color: getLanguageColor(item.key),
                                                            }))}
                                                        />
                                                    ),
                                                ]} />
                                        ),
                                    } satisfies SurfaceCardListItem]
                                    : []),
                            ]
                            return (
                                <SurfaceCardList
                                    label={t("publicProfile.coding.statsHeading")}
                                    items={statsItems}
                                />
                            )
                        }]
                        : []),
                    ...(solvedHistory.length > 0
                        ? [() => {
                            const facetBodyItems = [
                                ...(difficultyOptions.length > 0
                                    ? [() => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Typography type="body-xs" color="muted">{t("publicProfile.coding.manage.difficultyHeading")}</Typography>,
                                                () => (
                                                    <FlexWrapButtonRadio<DifficultyFilterValue>
                                                        ariaLabel={t("publicProfile.coding.manage.difficultyFilterAria")}
                                                        value={difficultyFilter}
                                                        onChange={setDifficultyFilter}
                                                        items={[
                                                            { value: "all", content: t("publicProfile.coding.manage.allDifficulties") },
                                                            ...difficultyOptions.map((raw) => {
                                                                const meta = CODING_DIFFICULTY_CHIP[raw]
                                                                return {
                                                                    value: raw,
                                                                    content: meta ? <StatusChip tone={meta.tone}>{t(meta.labelKey)}</StatusChip> : raw,
                                                                }
                                                            }),
                                                        ]}
                                                    />
                                                ),
                                            ]} />
                                    )]
                                    : []),
                                ...(languageOptions.length > 0
                                    ? [() => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                            items={[
                                                () => <Typography type="body-xs" color="muted">{t("publicProfile.coding.manage.languageHeading")}</Typography>,
                                                () => (
                                                    <FlexWrapButtonRadio<LanguageFilterValue>
                                                        ariaLabel={t("publicProfile.coding.manage.languageFilterAria")}
                                                        value={languageFilter}
                                                        onChange={setLanguageFilter}
                                                        items={[
                                                            { value: "all", content: t("publicProfile.coding.manage.allLanguages") },
                                                            ...languageOptions.map((lang) => ({
                                                                value: lang,
                                                                content: <LanguageChip language={lang} />,
                                                            })),
                                                        ]}
                                                    />
                                                ),
                                            ]} />
                                    )]
                                    : []),
                                ...(activeFacetCount > 0
                                    ? [() => (
                                        <Button variant="danger-soft" size="sm" className="self-start" onPress={clearFacets}>
                                            {t("publicProfile.coding.manage.clearFilters")}
                                        </Button>
                                    )]
                                    : []),
                            ]
                            return (
                                <SurfaceCardList
                                    label={t("publicProfile.coding.history")}
                                    items={[
                                        {
                                            key: "toolbar",
                                            content: () => (
                                                <Cluster gap={4} principle="content-row" justify="between"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackH gap={4} principle="content-row" classNames={["min-w-0", "flex-1"]}
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <SearchInput
                                                                            className="min-w-0 flex-1"
                                                                            value={search}
                                                                            onValueChange={setSearch}
                                                                            placeholder={t("publicProfile.coding.manage.searchPlaceholder")}
                                                                        />
                                                                    ),
                                                                    ...((difficultyOptions.length > 0 || languageOptions.length > 0)
                                                                        ? [() => (
                                                                            <Popover isOpen={filterOpen} onOpenChange={setFilterOpen}>
                                                                                <Button
                                                                                    isIconOnly
                                                                                    variant="ghost"
                                                                                    aria-label={t("publicProfile.coding.manage.filterButton")}
                                                                                    className="shrink-0"
                                                                                >
                                                                                    {activeFacetCount > 0 ? (
                                                                                        <Badge.Anchor>
                                                                                            <FunnelIcon className="size-5" />
                                                                                            <Badge size="sm" color="accent" placement="top-left">{activeFacetCount}</Badge>
                                                                                        </Badge.Anchor>
                                                                                    ) : (
                                                                                        <FunnelIcon className="size-5" />
                                                                                    )}
                                                                                </Button>
                                                                                <Popover.Content className="w-72">
                                                                                    <StackV gap={1} padding={4} principle="cell-pad"
                                                                                        explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                                                        items={[
                                                                                            () => (
                                                                                                <StackV gap={4} items={facetBodyItems} />
                                                                                            ),
                                                                                        ]} />
                                                                                </Popover.Content>
                                                                            </Popover>
                                                                        )]
                                                                        : []),
                                                                ]} />
                                                        ),
                                                        () => (
                                                            <Typography type="body-sm" color="muted" className="shrink-0">
                                                                {t("publicProfile.coding.manage.found", { count: filteredHistory.length })}
                                                            </Typography>
                                                        ),
                                                    ]} />
                                            ),
                                        },
                                        ...(filteredHistory.length === 0
                                            ? [{
                                                key: "empty-filtered",
                                                content: () => (
                                                    <Typography type="body-sm" color="muted">
                                                        {t("publicProfile.coding.manage.emptyFiltered")}
                                                    </Typography>
                                                ),
                                            } satisfies SurfaceCardListItem]
                                            : [
                                                ...visibleHistory.map((item, index) => {
                                                    const difficulty = CODING_DIFFICULTY_CHIP[item.difficulty]
                                                    const solvedAt = item.firstSolvedAt
                                                        ? new Date(item.firstSolvedAt).toLocaleDateString(locale)
                                                        : undefined
                                                    const chipItems = [
                                                        ...(difficulty
                                                            ? [() => (
                                                                <StatusChip tone={difficulty.tone}>
                                                                    {t(difficulty.labelKey)}
                                                                </StatusChip>
                                                            )]
                                                            : []),
                                                        ...(item.domain
                                                            ? [() => (
                                                                <StatusChip tone="neutral">
                                                                    {domainLabel(item.domain!)}
                                                                </StatusChip>
                                                            )]
                                                            : []),
                                                        ...item.languages.map((language) => (
                                                            () => <LanguageChip key={language} language={language} />
                                                        )),
                                                    ]
                                                    return {
                                                        key: `${item.slug}-${index}`,
                                                        hover: "underline" as const,
                                                        href: username
                                                            ? pathConfig().locale(locale).profile(username).skills().problem(item.slug).build()
                                                            : undefined,
                                                        content: () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <StackV gap={3} principle="sibling-stack" classNames={["min-w-0", "flex-1"]}
                                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => (
                                                                                    <Typography type="body-sm" weight="medium" truncate className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                                                        {item.problemTitle}
                                                                                    </Typography>
                                                                                ),
                                                                                ...(solvedAt
                                                                                    ? [() => (
                                                                                        <Typography type="body-xs" color="muted">
                                                                                            {solvedAt}
                                                                                        </Typography>
                                                                                    )]
                                                                                    : []),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <Cluster gap={3} principle="chip-row" justify="end" classNames={["shrink-0"]} items={chipItems}
                                                                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                                        />
                                                                    ),
                                                                ]} />
                                                        ),
                                                    } satisfies SurfaceCardListItem
                                                }),
                                                ...(hiddenHistory > 0
                                                    ? [{
                                                        key: "show-more",
                                                        onPress: () => setShowAllHistory((open) => !open),
                                                        content: () => (
                                                            <span className="text-muted">
                                                                {showAllHistory
                                                                    ? t("publicProfile.coding.showLess")
                                                                    : t("publicProfile.coding.showMore", { count: hiddenHistory })}
                                                            </span>
                                                        ),
                                                    } satisfies SurfaceCardListItem]
                                                    : []),
                                            ]),
                                    ]}
                                />
                            )
                        }]
                        : []),
                ]} />
        </AsyncContent>
    )
}

"use client"

import React from "react"
import {
    ProfileCoding,
} from "./ProfileCoding"
import {
    ProfileSectionGuard,
} from "@/components/blocks/profile/ProfileSectionGuard"

/** Props for {@link ProfileSkillsPage}. */
export type ProfileSkillsPageProps = Record<string, never>
/**
 * Skills tab ("Skills & Coding") of the public profile ΓÇö a sibling of the
 * Challenges tab. Delegates the whole tab to {@link ProfileCoding}, which leads
 * with the headline metric row, gathers the breakdowns into one "Stats" card, and
 * lists the solve history. Self-contained: it reads the username from the route,
 * drives its own SWR, and self-hides each block when there is nothing to show.
 *
 * @param props - optional className for the root element.
 */
export const ProfileSkillsPage = () => {
    return (
        <ProfileSectionGuard section="skills">
            <div className={"flex flex-col gap-6"}>
                {/* metric row ΓåÆ gathered stats card ΓåÆ solve history */}
                <ProfileCoding />
            </div>
        </ProfileSectionGuard>
    )
}
